import { Contact, User, ExportLog, Category } from '../types';

// Keys for localStorage
const KEYS = {
  USER: 'vcontact_user',
  CONTACTS: 'vcontact_contacts',
  EXPORTS: 'vcontact_exports',
};

// Simulation of a delay to mimic network requests
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// --- Auth Services ---

export const login = async (email: string): Promise<User> => {
  await delay(800); // Fake network delay

  // Hardcoded admin for demo purposes
  const role = email.toLowerCase().includes('admin') ? 'admin' : 'user';

  const user: User = {
    id: 'user_' + Math.random().toString(36).substr(2, 9),
    email,
    role,
    created_at: new Date().toISOString(),
  };

  localStorage.setItem(KEYS.USER, JSON.stringify(user));
  return user;
};

export const logout = async (): Promise<void> => {
  await delay(200);
  localStorage.removeItem(KEYS.USER);
};

export const getCurrentUser = (): User | null => {
  const stored = localStorage.getItem(KEYS.USER);
  return stored ? JSON.parse(stored) : null;
};

// --- Contact Services ---

export const getContacts = async (): Promise<Contact[]> => {
  await delay(300);
  const stored = localStorage.getItem(KEYS.CONTACTS);
  return stored ? JSON.parse(stored) : [];
};

export const addContact = async (contact: Omit<Contact, 'id' | 'created_at'>): Promise<Contact> => {
  await delay(300);
  const newContact: Contact = {
    ...contact,
    id: 'ct_' + Math.random().toString(36).substr(2, 9),
    created_at: new Date().toISOString(),
  };

  const contacts = await getContacts();
  const updatedContacts = [newContact, ...contacts];
  localStorage.setItem(KEYS.CONTACTS, JSON.stringify(updatedContacts));
  return newContact;
};

export const updateContact = async (id: string, updates: Partial<Contact>): Promise<Contact[]> => {
    await delay(200);
    const contacts = await getContacts();
    const updated = contacts.map(c => c.id === id ? { ...c, ...updates } : c);
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify(updated));
    return updated;
}

export const deleteContact = async (id: string): Promise<void> => {
  await delay(200);
  const contacts = await getContacts();
  const filtered = contacts.filter(c => c.id !== id);
  localStorage.setItem(KEYS.CONTACTS, JSON.stringify(filtered));
};

// --- Analytics / Exports ---

export const logExport = async (type: 'PDF' | 'EXCEL', userId: string): Promise<void> => {
  const logsRaw = localStorage.getItem(KEYS.EXPORTS);
  const logs: ExportLog[] = logsRaw ? JSON.parse(logsRaw) : [];

  const newLog: ExportLog = {
    id: 'exp_' + Math.random().toString(36).substr(2, 9),
    user_id: userId,
    type,
    created_at: new Date().toISOString(),
  };

  localStorage.setItem(KEYS.EXPORTS, JSON.stringify([...logs, newLog]));
};

export const getExportLogs = async (): Promise<ExportLog[]> => {
    const logsRaw = localStorage.getItem(KEYS.EXPORTS);
    return logsRaw ? JSON.parse(logsRaw) : [];
}

// --- Seed Data (for First Run) ---
export const seedDataIfNeeded = () => {
  if (!localStorage.getItem(KEYS.CONTACTS)) {
    const mockContacts: Contact[] = [
      { id: '1', user_id: 'demo', name: 'Alice Chen', phone: '+1 555-0101', email: 'alice@tech.io', category: 'Business', note: 'Met at SaaS summit', created_at: new Date().toISOString() },
      { id: '2', user_id: 'demo', name: 'Bob Smith', phone: '+1 555-0102', email: 'bob@marketing.com', category: 'Creator', note: 'Interested in collabs', created_at: new Date().toISOString() },
      { id: '3', user_id: 'demo', name: 'Charlie Davis', phone: '+1 555-0103', email: 'charlie@uni.edu', category: 'Student', note: 'Intern candidate', created_at: new Date().toISOString() },
    ];
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify(mockContacts));
  }
};

import { Contact } from '../types';

export const exportToCSV = (contacts: Contact[], filename = 'vcontact-export.csv') => {
  const headers = ['Name', 'Phone', 'Email', 'Category', 'Note', 'Created At'];

  const csvContent = [
    headers.join(','),
    ...contacts.map(c => {
        const row = [
            `"${c.name}"`,
            `"${c.phone}"`,
            `"${c.email}"`,
            `"${c.category}"`,
            `"${c.note}"`,
            `"${new Date(c.created_at).toLocaleDateString()}"`
        ];
        return row.join(',');
    })
  ].join('\n');

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  if (link.download !== undefined) {
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
};

export const printView = () => {
    window.print();
};

