  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingContact) {
        await updateContact(editingContact.id, formData);
    } else {
        await addContact({ ...formData, user_id: user.id });
    }
    setIsModalOpen(false);
    setEditingContact(null);
