import React, { useState, useEffect } from 'react';
import { Auth } from './components/Auth';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { AdminDashboard } from './components/AdminDashboard';
import { getCurrentUser, login, logout, seedDataIfNeeded } from './services/storage';
import { User } from './types';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState('dashboard'); // 'dashboard', 'stats', 'profile'
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check local storage for session
    const storedUser = getCurrentUser();
    if (storedUser) {
      setUser(storedUser);
    }
    seedDataIfNeeded();
    setLoading(false);
  }, []);

  const handleLogin = async (email: string) => {
    const newUser = await login(email);
    setUser(newUser);
    setView('dashboard');
  };

  const handleLogout = async () => {
    await logout();
    setUser(null);
  };

  if (loading) return (
      <div className="min-h-screen bg-[#0B0F19] flex items-center justify-center">
          <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
  );

  if (!user) {
    return <Auth onLogin={handleLogin} />;
  }

  const renderContent = () => {
    switch (view) {
      case 'dashboard':
        return <Dashboard user={user} />;
      case 'stats':
        return user.role === 'admin' ? <AdminDashboard /> : <div className="text-white p-4">Access Restricted</div>;
      case 'profile':
        return (
            <div className="glass-panel p-8 rounded-2xl max-w-2xl mx-auto text-center animate-fade-in">
                <div className="w-24 h-24 bg-gradient-to-r from-primary to-secondary rounded-full mx-auto mb-6 flex items-center justify-center text-4xl font-bold text-white">
                    {user.email.charAt(0).toUpperCase()}
                </div>
                <h2 className="text-2xl font-bold text-white mb-2">{user.email}</h2>
                <span className="px-3 py-1 bg-white/10 rounded-full text-xs text-slate-300 uppercase tracking-widest">{user.role}</span>

                <div className="mt-8 pt-8 border-t border-white/5 grid grid-cols-2 gap-4 text-left">
                    <div>
                        <p className="text-slate-500 text-xs uppercase mb-1">Member Since</p>
                        <p className="text-white">{new Date(user.created_at).toLocaleDateString()}</p>
                    </div>
                    <div>
                        <p className="text-slate-500 text-xs uppercase mb-1">Account ID</p>
                        <p className="text-white font-mono text-xs">{user.id}</p>
                    </div>
                </div>
            </div>
        );
      default:
        return <Dashboard user={user} />;
    }
  };

  return (
    <Layout user={user} onLogout={handleLogout} currentPage={view} onNavigate={setView}>
      {renderContent()}
    </Layout>
  );
}

export default App;

