                    <div className="pt-2">
                        <button type="submit" className="w-full bg-gradient-to-r from-primary to-accent py-3.5 rounded-xl font-bold text-white shadow-lg shadow-primary/25 hover:shadow-primary/40 transition-all hover:-translate-y-0.5 active:scale-95">
                            {editingContact ? 'Save Changes' : 'Secure Connection'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { ArrowRight, Sparkles, Mail, CheckCircle2 } from 'lucide-react';

interface AuthProps {
  onLogin: (email: string) => void;
}

export const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [sent, setSent] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;
    setLoading(true);

    // Simulate API call for magic link
    setTimeout(() => {
        setSent(true);
        // Auto login for demo purposes after "clicking" link
        setTimeout(() => {
            onLogin(email);
        }, 1500);
    }, 1000);
  };

  return (
    <div className="min-h-screen bg-[#0B0F19] flex items-center justify-center p-4 relative overflow-hidden">
