// Keys for localStorage
const KEYS = {
  USER: 'vcontact_user',
  CONTACTS: 'vcontact_contacts',
  EXPORTS: 'vcontact_exports',
};

// Simulation of a delay to mimic network requests
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

