import React, { useState, useEffect } from 'react';
import { Auth } from './components/Auth';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { AdminDashboard } from './components/AdminDashboard';
import { Profile } from './components/Profile';
import { getCurrentUser, login, logout, seedDataIfNeeded } from './services/storage';
import { User } from './types';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState('dashboard'); // 'dashboard', 'stats', 'profile'
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check local storage for session
    const storedUser = getCurrentUser();
    if (storedUser) {
      setUser(storedUser);
    }
    seedDataIfNeeded();
    setLoading(false);
  }, []);

  const handleLogin = async (email: string) => {
    const newUser = await login(email);
    setUser(newUser);
    setView('dashboard');
  };

  const handleLogout = async () => {
    await logout();
    setUser(null);
  };

  const handleUpdateUser = (updatedUser: User) => {
      setUser(updatedUser);
  };

  if (loading) return (
      <div className="min-h-screen bg-[#0B0F19] flex items-center justify-center">
          <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
  );

  if (!user) {
    return <Auth onLogin={handleLogin} />;
  }

  const renderContent = () => {
    switch (view) {
      case 'dashboard':
        return <Dashboard user={user} />;
      case 'stats':
        return user.role === 'admin' ? <AdminDashboard /> : <div className="text-white p-4">Access Restricted</div>;
      case 'profile':
        return <Profile user={user} onUpdate={handleUpdateUser} />;
      default:
        return <Dashboard user={user} />;
    }
  };

  return (
    <Layout user={user} onLogout={handleLogout} currentPage={view} onNavigate={setView}>
      {renderContent()}
    </Layout>
  );
}

export default App;

