// Keys for localStorage
const KEYS = {
  USER: 'vcontact_user',
  CONTACTS: 'vcontact_contacts',
  EXPORTS: 'vcontact_exports',
};

// Simulation of a delay to mimic network requests
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// --- Auth Services ---

export const login = async (email: string): Promise<User> => {
  await delay(800); 

  // Create a consistent ID based on email to simulate a real DB user record persistence
  // In a real app, this comes from the backend. 
  // Here we use btoa to make a pseudo-consistent ID so data persists across logins for the same email.
  const pseudoId = 'user_' + btoa(email).replace(/=/g, '').substring(0, 12);
  const role = email.toLowerCase().includes('admin') ? 'admin' : 'user';

  // Try to recover existing user to keep profile updates
  const storedUserRaw = localStorage.getItem(KEYS.USER);
  if (storedUserRaw) {
      const storedUser = JSON.parse(storedUserRaw);
      if (storedUser.email === email) {
          return storedUser;
      }
  }

  const user: User = {
    id: pseudoId,
    email,
    role,
    created_at: new Date().toISOString(),
    name: email.split('@')[0], // Default name
    preferences: {
        theme: 'dark',
        notifications: true,
        publicProfile: false,
        language: 'en'
    }
  };

  localStorage.setItem(KEYS.USER, JSON.stringify(user));
  return user;
};

export const logout = async (): Promise<void> => {
  await delay(200);
  localStorage.removeItem(KEYS.USER);
};

export const getCurrentUser = (): User | null => {
  const stored = localStorage.getItem(KEYS.USER);
  return stored ? JSON.parse(stored) : null;
};

export const updateUser = async (updates: Partial<User>): Promise<User> => {
  await delay(500);
  const stored = localStorage.getItem(KEYS.USER);
  if (!stored) throw new Error("No active session");

  const currentUser = JSON.parse(stored);
  const updatedUser = { 
      ...currentUser, 
      ...updates,
      preferences: { ...currentUser.preferences, ...updates.preferences } 
  };

  localStorage.setItem(KEYS.USER, JSON.stringify(updatedUser));
  return updatedUser;
};

// --- Contact Services ---

// Now requires userId to ensure we only fetch data for the specific logged-in user
// Made userId optional to allow AdminDashboard to fetch all contacts
export const getContacts = async (userId?: string): Promise<Contact[]> => {
  await delay(300);
  const stored = localStorage.getItem(KEYS.CONTACTS);
  const allContacts: Contact[] = stored ? JSON.parse(stored) : [];

  if (!userId) {
    return allContacts;
  }

  // Strict filtering by User ID
  return allContacts.filter(c => c.user_id === userId);
};

export const addContact = async (contact: Omit<Contact, 'id' | 'created_at'>): Promise<Contact> => {
  await delay(300);
  const newContact: Contact = {
    ...contact,
    id: 'ct_' + Math.random().toString(36).substr(2, 9),
    created_at: new Date().toISOString(),
  };

  const stored = localStorage.getItem(KEYS.CONTACTS);
  const allContacts: Contact[] = stored ? JSON.parse(stored) : [];

  const updatedContacts = [newContact, ...allContacts];
  localStorage.setItem(KEYS.CONTACTS, JSON.stringify(updatedContacts));
  return newContact;
};

export const updateContact = async (id: string, updates: Partial<Contact>): Promise<Contact[]> => {
    await delay(200);
    const stored = localStorage.getItem(KEYS.CONTACTS);
    const allContacts: Contact[] = stored ? JSON.parse(stored) : [];

    const updated = allContacts.map(c => c.id === id ? { ...c, ...updates } : c);
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify(updated));
    return updated.filter(c => c.user_id === updates.user_id); // Return only user's contacts
}

export const deleteContact = async (id: string): Promise<void> => {
  await delay(200);
  const stored = localStorage.getItem(KEYS.CONTACTS);
  const allContacts: Contact[] = stored ? JSON.parse(stored) : [];

  const filtered = allContacts.filter(c => c.id !== id);
  localStorage.setItem(KEYS.CONTACTS, JSON.stringify(filtered));
};

// --- Analytics / Exports ---

export const logExport = async (type: 'PDF' | 'EXCEL', userId: string): Promise<void> => {
  const logsRaw = localStorage.getItem(KEYS.EXPORTS);
  const logs: ExportLog[] = logsRaw ? JSON.parse(logsRaw) : [];

  const newLog: ExportLog = {
    id: 'exp_' + Math.random().toString(36).substr(2, 9),
    user_id: userId,
    type,
    created_at: new Date().toISOString(),
  };

  localStorage.setItem(KEYS.EXPORTS, JSON.stringify([...logs, newLog]));
};

export const getExportLogs = async (): Promise<ExportLog[]> => {
    const logsRaw = localStorage.getItem(KEYS.EXPORTS);
    return logsRaw ? JSON.parse(logsRaw) : [];
}

// --- NO FAKE DATA SEEDING ---
export const seedDataIfNeeded = () => {
  if (!localStorage.getItem(KEYS.CONTACTS)) {
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify([]));
  }
};

