import { Contact } from '../types';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

// Extend jsPDF type to include autoTable (added by the plugin)
interface jsPDFWithAutoTable extends jsPDF {
  autoTable: (options: any) => void;
  lastAutoTable: { finalY: number };
}

export const exportToCSV = (contacts: Contact[], filename = 'vcontact-export.csv') => {
  const headers = ['Name', 'Phone', 'Email', 'Category', 'Note', 'Created At'];

  const csvContent = [
    headers.join(','),
    ...contacts.map(c => {
        const row = [
            `"${c.name}"`,
            `"${c.phone}"`,
            `"${c.email}"`,
            `"${c.category}"`,
            `"${c.note}"`,
            `"${new Date(c.created_at).toLocaleDateString()}"`
        ];
        return row.join(',');
    })
  ].join('\n');

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  if (link.download !== undefined) {
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
};

export const exportToPDF = (contacts: Contact[], userEmail: string) => {
    const doc = new jsPDF() as jsPDFWithAutoTable;

    // Header
    doc.setFontSize(20);
    doc.setTextColor(99, 102, 241); // Primary Color (Indigo)
    doc.text('VContact Network Export', 14, 22);

    doc.setFontSize(10);
    doc.setTextColor(100);
    doc.text(`Generated for: ${userEmail}`, 14, 30);
    doc.text(`Date: ${new Date().toLocaleDateString()}`, 14, 35);

    // Table
    const tableColumn = ["Name", "Category", "Phone", "Email", "Note"];
    const tableRows = [];

    contacts.forEach(contact => {
        const contactData = [
            contact.name,
            contact.category,
            contact.phone,
            contact.email,
            contact.note
        ];
        tableRows.push(contactData);
    });

    doc.autoTable({
        head: [tableColumn],
        body: tableRows,
        startY: 40,
        theme: 'grid',
        headStyles: { fillColor: [99, 102, 241] },
        styles: { fontSize: 8 },
        alternateRowStyles: { fillColor: [245, 247, 255] }
    });

    // Footer
    const finalY = (doc as any).lastAutoTable.finalY || 200;
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text('Securely generated by VContact System.', 14, finalY + 10);

    doc.save(`vcontact_export_${new Date().toISOString().slice(0,10)}.pdf`);
};

