      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingContact) {
        await updateContact(editingContact.id, { ...formData, user_id: user.id });
    } else {
        await addContact({ ...formData, user_id: user.id });
    }
    setIsModalOpen(false);
