                    <div className="pt-2">
                        <button type="submit" className="w-full bg-gradient-to-r from-primary to-accent py-3.5 rounded-xl font-bold text-white shadow-lg shadow-primary/25 hover:shadow-primary/40 transition-all hover:-translate-y-0.5 active:scale-95">
