interface AuthProps {
  onLogin: (email: string) => void;
}

export const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [isGoogleLoading, setIsGoogleLoading] = useState(false);
  const [sent, setSent] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;
    setLoading(true);

    // Simulate API call for magic link
    setTimeout(() => {
        setSent(true);
        // Auto login for demo purposes after "clicking" link
        setTimeout(() => {
            onLogin(email);
        }, 1500);
    }, 1000);
  };

  const handleGoogleLogin = () => {
    setIsGoogleLoading(true);

    // Create a simulation of a Google Popup Window
    const width = 500;
    const height = 600;
    const left = (window.screen.width / 2) - (width / 2);
    const top = (window.screen.height / 2) - (height / 2);

    const popup = window.open(
        '', 
        'Google Auth', 
        `width=${width},height=${height},top=${top},left=${left},scrollbars=yes,resizable=yes`
    );

    if (popup) {
        popup.document.write(`
            <html>
            <head>
                <title>Sign in with Google</title>
                <style>
                    body { font-family: 'Roboto', arial, sans-serif; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; background: #fff; }
                    .container { text-align: center; }
                    .loader { border: 4px solid #f3f3f3; border-top: 4px solid #4285F4; border-radius: 50%; width: 40px; height: 40px; animation: spin 1s linear infinite; margin: 0 auto 20px; }
                    @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
                    h2 { color: #202124; font-weight: 500; }
                    p { color: #5f6368; }
                </style>
            </head>
            <body>
                <div class="container">
                    <div class="loader"></div>
                    <h2>Signing in...</h2>
                    <p>Securely connecting to VContact</p>
                </div>
                <script>
                    setTimeout(() => {
                        window.close();
                    }, 2000);
                </script>
            </body>
            </html>
        `);

        // Polling to see if popup is closed
        const timer = setInterval(() => {
            if (popup.closed) {
                clearInterval(timer);
                setIsGoogleLoading(false);
                onLogin('google_user@gmail.com');
            }
        }, 500);
    } else {
        // Fallback if popup blocked
        setTimeout(() => {
            setIsGoogleLoading(false);
