import { Contact } from '../types';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

export const exportToCSV = (contacts: Contact[], filename = 'vcontact-export.csv') => {
  const headers = ['Name', 'Phone', 'Email', 'Category', 'Note', 'Created At'];

  const csvContent = [
    headers.join(','),
    ...contacts.map(c => {
        const row = [
            `"${c.name}"`,
            `"${c.phone}"`,
            `"${c.email}"`,
            `"${c.category}"`,
            `"${c.note}"`,
            `"${new Date(c.created_at).toLocaleDateString()}"`
        ];
        return row.join(',');
    })
  ].join('\n');

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  if (link.download !== undefined) {
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
};

export const exportToPDF = (contacts: Contact[], userEmail: string) => {
    const doc: any = new jsPDF();

    // Header
    doc.setFontSize(20);
    doc.setTextColor(99, 102, 241); // Primary Color (Indigo)
    doc.text('VContact Network Export', 14, 22);

    doc.setFontSize(10);
    doc.setTextColor(100);
    doc.text(`Generated for: ${userEmail}`, 14, 30);
    doc.text(`Date: ${new Date().toLocaleDateString()}`, 14, 35);

    // Table
    const tableColumn = ["Name", "Category", "Phone", "Email", "Note"];
    const tableRows: any[] = [];

    contacts.forEach(contact => {
        const contactData = [
            contact.name,
            contact.category,
            contact.phone,
            contact.email,
            contact.note
        ];
        tableRows.push(contactData);
    });

    doc.autoTable({
        head: [tableColumn],
        body: tableRows,
        startY: 40,
        theme: 'grid',
        headStyles: { fillColor: [99, 102, 241] },
        styles: { fontSize: 8 },
        alternateRowStyles: { fillColor: [245, 247, 255] }
    });

    // Footer
    const finalY = doc.lastAutoTable?.finalY || 200;
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text('Securely generated by VContact System.', 14, finalY + 10);

    doc.save(`vcontact_export_${new Date().toISOString().slice(0,10)}.pdf`);
};

import { Contact, User, ExportLog, Category } from '../types';

// Keys for localStorage
const KEYS = {
  USER: 'vcontact_user',
  CONTACTS: 'vcontact_contacts',
  EXPORTS: 'vcontact_exports',
};

// Simulation of a delay to mimic network requests
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// --- Auth Services ---

export const login = async (email: string): Promise<User> => {
  await delay(800); 

  // Create a consistent ID based on email to simulate a real DB user record persistence
  // In a real app, this comes from the backend. 
  // Here we use btoa to make a pseudo-consistent ID so data persists across logins for the same email.
  const pseudoId = 'user_' + btoa(email).replace(/=/g, '').substring(0, 12);
  const role = email.toLowerCase().includes('admin') ? 'admin' : 'user';

  // Try to recover existing user to keep profile updates
  const storedUserRaw = localStorage.getItem(KEYS.USER);
  if (storedUserRaw) {
      const storedUser = JSON.parse(storedUserRaw);
      if (storedUser.email === email) {
          return storedUser;
      }
  }

  const user: User = {
    id: pseudoId,
    email,
    role,
    created_at: new Date().toISOString(),
    name: email.split('@')[0], // Default name
    preferences: {
        theme: 'dark',
        notifications: true,
        publicProfile: false,
        language: 'en'
    }
  };

  localStorage.setItem(KEYS.USER, JSON.stringify(user));
  return user;
};

export const logout = async (): Promise<void> => {
  await delay(200);
  localStorage.removeItem(KEYS.USER);
};

export const deleteAccount = async (userId: string): Promise<void> => {
  await delay(800);

  // 1. Remove current session user
  localStorage.removeItem(KEYS.USER);

  // 2. Remove all contacts belonging to this user
  const storedContacts = localStorage.getItem(KEYS.CONTACTS);
  if (storedContacts) {
    const allContacts: Contact[] = JSON.parse(storedContacts);
    const keptContacts = allContacts.filter(c => c.user_id !== userId);
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify(keptContacts));
  }

  // 3. Remove logs
  const storedLogs = localStorage.getItem(KEYS.EXPORTS);
  if (storedLogs) {
      const allLogs: ExportLog[] = JSON.parse(storedLogs);
      const keptLogs = allLogs.filter(l => l.user_id !== userId);
      localStorage.setItem(KEYS.EXPORTS, JSON.stringify(keptLogs));
  }
};

export const getCurrentUser = (): User | null => {
  const stored = localStorage.getItem(KEYS.USER);
  return stored ? JSON.parse(stored) : null;
};

export const updateUser = async (updates: Partial<User>): Promise<User> => {
  await delay(500);
  const stored = localStorage.getItem(KEYS.USER);
  if (!stored) throw new Error("No active session");

  const currentUser = JSON.parse(stored);
  const updatedUser = { 
      ...currentUser, 
      ...updates,
      preferences: { ...currentUser.preferences, ...updates.preferences } 
  };

  localStorage.setItem(KEYS.USER, JSON.stringify(updatedUser));
  return updatedUser;
};

// --- Contact Services ---

// Now requires userId to ensure we only fetch data for the specific logged-in user
// Made userId optional to allow AdminDashboard to fetch all contacts
export const getContacts = async (userId?: string): Promise<Contact[]> => {
  await delay(300);
  const stored = localStorage.getItem(KEYS.CONTACTS);
  const allContacts: Contact[] = stored ? JSON.parse(stored) : [];

  if (!userId) {
    return allContacts;
  }

  // Strict filtering by User ID
  return allContacts.filter(c => c.user_id === userId);
};

export const addContact = async (contact: Omit<Contact, 'id' | 'created_at'>): Promise<Contact> => {
  await delay(300);
  const newContact: Contact = {
    ...contact,
    id: 'ct_' + Math.random().toString(36).substr(2, 9),
    created_at: new Date().toISOString(),
  };

  const stored = localStorage.getItem(KEYS.CONTACTS);
  const allContacts: Contact[] = stored ? JSON.parse(stored) : [];

  const updatedContacts = [newContact, ...allContacts];
  localStorage.setItem(KEYS.CONTACTS, JSON.stringify(updatedContacts));
  return newContact;
};

export const updateContact = async (id: string, updates: Partial<Contact>): Promise<Contact[]> => {
    await delay(200);
    const stored = localStorage.getItem(KEYS.CONTACTS);
    const allContacts: Contact[] = stored ? JSON.parse(stored) : [];

    const updated = allContacts.map(c => c.id === id ? { ...c, ...updates } : c);
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify(updated));
    return updated.filter(c => c.user_id === updates.user_id); // Return only user's contacts
}

export const deleteContact = async (id: string): Promise<void> => {
  await delay(200);
  const stored = localStorage.getItem(KEYS.CONTACTS);
  const allContacts: Contact[] = stored ? JSON.parse(stored) : [];

  const filtered = allContacts.filter(c => c.id !== id);
  localStorage.setItem(KEYS.CONTACTS, JSON.stringify(filtered));
};

// --- Analytics / Exports ---

export const logExport = async (type: 'PDF' | 'EXCEL', userId: string): Promise<void> => {
  const logsRaw = localStorage.getItem(KEYS.EXPORTS);
  const logs: ExportLog[] = logsRaw ? JSON.parse(logsRaw) : [];

  const newLog: ExportLog = {
    id: 'exp_' + Math.random().toString(36).substr(2, 9),
    user_id: userId,
    type,
    created_at: new Date().toISOString(),
  };

  localStorage.setItem(KEYS.EXPORTS, JSON.stringify([...logs, newLog]));
};

export const getExportLogs = async (): Promise<ExportLog[]> => {
    const logsRaw = localStorage.getItem(KEYS.EXPORTS);
    return logsRaw ? JSON.parse(logsRaw) : [];
}

// --- NO FAKE DATA SEEDING ---
export const seedDataIfNeeded = () => {
  if (!localStorage.getItem(KEYS.CONTACTS)) {
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify([]));
  }
};

import React, { useState, useEffect } from 'react';
import { Auth } from './components/Auth';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { AdminDashboard } from './components/AdminDashboard';
import { Profile } from './components/Profile';
import { getCurrentUser, login, logout, seedDataIfNeeded, deleteAccount } from './services/storage';
import { User } from './types';

interface Ripple {
  id: number;
  x: number;
  y: number;
}

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState('dashboard'); // 'dashboard', 'stats', 'profile'
  const [loading, setLoading] = useState(true);

  // Ripple Effect State
  const [ripples, setRipples] = useState<Ripple[]>([]);

  useEffect(() => {
    // Check local storage for session
    const storedUser = getCurrentUser();
    if (storedUser) {
      setUser(storedUser);
    }
    seedDataIfNeeded();
    setLoading(false);
  }, []);

  // Theme & Language Effect Engine
  useEffect(() => {
      const root = window.document.documentElement;

      // Theme Logic
      root.classList.remove('light', 'dark');
      const themePreference = user?.preferences?.theme || 'dark';

      if (themePreference === 'system') {
          const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
          root.classList.add(systemTheme);
      } else {
          root.classList.add(themePreference);
      }

      // Language Logic (Placeholder for full i18n implementation)
      root.setAttribute('lang', user?.preferences?.language || 'en');

  }, [user?.preferences?.theme, user?.preferences?.language]);

  // Global Pointer Listener for Echo Effect
  useEffect(() => {
    const handlePointerDown = (e: PointerEvent) => {
      // Limit number of ripples to prevent performance issues
      setRipples(prev => {
        if (prev.length > 5) return prev.slice(1);
        return prev;
      });

      const newRipple = {
        id: Date.now(),
        x: e.clientX,
        y: e.clientY
      };

      setRipples(prev => [...prev, newRipple]);

      // Remove ripple after animation completes
      setTimeout(() => {
        setRipples(prev => prev.filter(r => r.id !== newRipple.id));
      }, 600);
    };

    window.addEventListener('pointerdown', handlePointerDown);
    return () => window.removeEventListener('pointerdown', handlePointerDown);
  }, []);

  const handleLogin = async (email: string) => {
    const newUser = await login(email);
    setUser(newUser);
    setView('dashboard');
  };

  const handleLogout = async () => {
    await logout();
    setUser(null);
  };

  const handleDeleteAccount = async () => {
      if (user) {
          setLoading(true);
          await deleteAccount(user.id);
          setUser(null);
          setLoading(false);
      }
  };

  // Immediate Update function to make UI responsive
  const handleUpdateUser = (updatedUser: User) => {
      setUser(prev => ({...updatedUser}));
  };

  const renderContent = () => {
    switch (view) {
      case 'dashboard':
        return <Dashboard user={user!} />;
      case 'stats':
        return user?.role === 'admin' ? <AdminDashboard /> : <div className="text-white p-4">Access Restricted</div>;
      case 'profile':
        return <Profile user={user!} onUpdate={handleUpdateUser} onDelete={handleDeleteAccount} />;
      default:
        return <Dashboard user={user!} />;
    }
  };

  if (loading) return (
      <div className="min-h-screen bg-[#0B0F19] flex items-center justify-center">
          <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
  );

  return (
    <>
      {/* Global Echo FX Layer */}
      <div className="fixed inset-0 pointer-events-none z-[9999] overflow-hidden">
        {ripples.map(ripple => (
          <div
            key={ripple.id}
            className="absolute rounded-full border-2 border-primary/40 bg-primary/10 animate-ripple shadow-[0_0_15px_rgba(99,102,241,0.5)]"
            style={{
              left: ripple.x,
              top: ripple.y,
              width: '20px',
              height: '20px',
              marginLeft: '-10px',
              marginTop: '-10px',
            }}
          />
        ))}
      </div>

      {!user ? (
        <Auth onLogin={handleLogin} />
      ) : (
        <Layout user={user} onLogout={handleLogout} currentPage={view} onNavigate={setView}>
          {renderContent()}
        </Layout>
      )}
    </>
  );
}

export default App;

