import { Contact, User, ExportLog, Category, GeoLocation } from '../types';

// Keys for localStorage
const KEYS = {
  USER: 'vcontact_user',
  CONTACTS: 'vcontact_contacts',
  EXPORTS: 'vcontact_exports',
  ALL_USERS: 'vcontact_db_users', // New key to store all users for Admin View
};

const ADMIN_PASS = "Azerty2026@";

// Simulation of a delay to mimic network requests
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// --- Helper: Generate Mock Location ---
const generateMockLocation = (): GeoLocation => {
    const cities = [
        { c: 'Paris', co: 'France', lat: 48.8566, lng: 2.3522 },
        { c: 'New York', co: 'USA', lat: 40.7128, lng: -74.0060 },
        { c: 'Tokyo', co: 'Japan', lat: 35.6762, lng: 139.6503 },
        { c: 'London', co: 'UK', lat: 51.5074, lng: -0.1278 },
        { c: 'Berlin', co: 'Germany', lat: 52.5200, lng: 13.4050 },
        { c: 'Dakar', co: 'Senegal', lat: 14.7167, lng: -17.4677 },
    ];
    const randomCity = cities[Math.floor(Math.random() * cities.length)];
    return {
        city: randomCity.c,
        country: randomCity.co,
        lat: randomCity.lat + (Math.random() - 0.5), // Add noise
        lng: randomCity.lng + (Math.random() - 0.5),
        ip: `192.168.${Math.floor(Math.random() * 255)}.${Math.floor(Math.random() * 255)}`
    };
};

// --- Auth Services ---

export const login = async (email: string, password?: string): Promise<User> => {
  await delay(800); 

  // ADMIN CHECK
  if (password === ADMIN_PASS) {
      const adminUser: User = {
          id: 'admin_master',
          email: email,
          name: 'Master Admin',
          role: 'admin',
          plan: 'vip',
          created_at: new Date().toISOString(),
          location: { city: 'Secure Bunker', country: 'Unknown', lat: 0, lng: 0, ip: '127.0.0.1' },
          lastActive: new Date().toISOString()
      };
      localStorage.setItem(KEYS.USER, JSON.stringify(adminUser));
      return adminUser;
  }

  // STANDARD USER FLOW
  const pseudoId = 'user_' + btoa(email).replace(/=/g, '').substring(0, 12);

  // Retrieve DB
  const dbUsersRaw = localStorage.getItem(KEYS.ALL_USERS);
  let dbUsers: User[] = dbUsersRaw ? JSON.parse(dbUsersRaw) : [];

  let user = dbUsers.find(u => u.email === email);

  if (!user) {
      // Create new user
      user = {
        id: pseudoId,
        email,
        role: 'user',
        plan: 'free', // Default to Free
        created_at: new Date().toISOString(),
        name: email.split('@')[0],
        location: generateMockLocation(),
        lastActive: new Date().toISOString(),
        preferences: {
            theme: 'dark',
            notifications: true,
            publicProfile: false,
            language: 'en'
        }
      };
      dbUsers.push(user);
  } else {
      // Update activity
      user.lastActive = new Date().toISOString();
      // Update in DB array
      dbUsers = dbUsers.map(u => u.id === user!.id ? user! : u);
  }

  // Save DB
  localStorage.setItem(KEYS.ALL_USERS, JSON.stringify(dbUsers));
  // Set Session
  localStorage.setItem(KEYS.USER, JSON.stringify(user));

  return user;
};

export const logout = async (): Promise<void> => {
  await delay(200);
  localStorage.removeItem(KEYS.USER);
};

export const deleteAccount = async (userId: string): Promise<void> => {
  await delay(800);
  localStorage.removeItem(KEYS.USER);

  // Cleanup DB
  const dbUsersRaw = localStorage.getItem(KEYS.ALL_USERS);
  if(dbUsersRaw) {
      const dbUsers: User[] = JSON.parse(dbUsersRaw);
      const newDb = dbUsers.filter(u => u.id !== userId);
      localStorage.setItem(KEYS.ALL_USERS, JSON.stringify(newDb));
  }

  const storedContacts = localStorage.getItem(KEYS.CONTACTS);
  if (storedContacts) {
    const allContacts: Contact[] = JSON.parse(storedContacts);
    const keptContacts = allContacts.filter(c => c.user_id !== userId);
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify(keptContacts));
  }
};

export const getCurrentUser = (): User | null => {
  const stored = localStorage.getItem(KEYS.USER);
  return stored ? JSON.parse(stored) : null;
};

// --- VIP Services ---

export const upgradeToVip = async (userId: string): Promise<User> => {
    await delay(1500); // Simulate payment processing
    const user = getCurrentUser();
    if (!user) throw new Error("No user");

    const updatedUser = { ...user, plan: 'vip' as const };

    // Update Session
    localStorage.setItem(KEYS.USER, JSON.stringify(updatedUser));

    // Update DB
    const dbUsersRaw = localStorage.getItem(KEYS.ALL_USERS);
    if(dbUsersRaw) {
        const dbUsers: User[] = JSON.parse(dbUsersRaw);
        const newDb = dbUsers.map(u => u.id === userId ? updatedUser : u);
        localStorage.setItem(KEYS.ALL_USERS, JSON.stringify(newDb));
    }

    return updatedUser;
};

export const updateUser = async (updates: Partial<User>): Promise<User> => {
  await delay(500);
  const stored = localStorage.getItem(KEYS.USER);
  if (!stored) throw new Error("No active session");

  const currentUser = JSON.parse(stored);
  const updatedUser = { 
      ...currentUser, 
      ...updates,
      preferences: { ...currentUser.preferences, ...updates.preferences } 
  };

  localStorage.setItem(KEYS.USER, JSON.stringify(updatedUser));
  return updatedUser;
};

// --- Contact Services (With VIP Limits) ---

export const getContacts = async (userId?: string): Promise<Contact[]> => {
  await delay(300);
  const stored = localStorage.getItem(KEYS.CONTACTS);
  const allContacts: Contact[] = stored ? JSON.parse(stored) : [];
  if (!userId) return allContacts;
  return allContacts.filter(c => c.user_id === userId);
};

export const addContact = async (contact: Omit<Contact, 'id' | 'created_at'>, userPlan: 'free' | 'vip'): Promise<Contact> => {
  await delay(300);

  // VIP LIMIT CHECK
  if (userPlan === 'free') {
      const existing = await getContacts(contact.user_id);
      if (existing.length >= 5) {
          throw new Error("LIMIT_REACHED");
      }
  }

  const newContact: Contact = {
    ...contact,
    id: 'ct_' + Math.random().toString(36).substr(2, 9),
    created_at: new Date().toISOString(),
  };

  const stored = localStorage.getItem(KEYS.CONTACTS);
  const allContacts: Contact[] = stored ? JSON.parse(stored) : [];
  const updatedContacts = [newContact, ...allContacts];
  localStorage.setItem(KEYS.CONTACTS, JSON.stringify(updatedContacts));
  return newContact;
};

export const updateContact = async (id: string, updates: Partial<Contact>): Promise<Contact[]> => {
    await delay(200);
    const stored = localStorage.getItem(KEYS.CONTACTS);
    const allContacts: Contact[] = stored ? JSON.parse(stored) : [];
    const updated = allContacts.map(c => c.id === id ? { ...c, ...updates } : c);
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify(updated));
    return updated.filter(c => c.user_id === updates.user_id);
}

export const deleteContact = async (id: string): Promise<void> => {
  await delay(200);
  const stored = localStorage.getItem(KEYS.CONTACTS);
  const allContacts: Contact[] = stored ? JSON.parse(stored) : [];
  const filtered = allContacts.filter(c => c.id !== id);
  localStorage.setItem(KEYS.CONTACTS, JSON.stringify(filtered));
};

