export const logExport = async (type: 'PDF' | 'EXCEL', userId: string): Promise<void> => {
  const logsRaw = localStorage.getItem(KEYS.EXPORTS);
  const logs: ExportLog[] = logsRaw ? JSON.parse(logsRaw) : [];
  const newLog: ExportLog = {
    id: 'exp_' + Math.random().toString(36).substr(2, 9),
    user_id: userId,
    type,
    created_at: new Date().toISOString(),
  };
  localStorage.setItem(KEYS.EXPORTS, JSON.stringify([...logs, newLog]));
};

export const getExportLogs = async (): Promise<ExportLog[]> => {
    const logsRaw = localStorage.getItem(KEYS.EXPORTS);
    return logsRaw ? JSON.parse(logsRaw) : [];
}

export const getAllUsers = async (): Promise<User[]> => {
    const raw = localStorage.getItem(KEYS.ALL_USERS);
    return raw ? JSON.parse(raw) : [];
};

export const seedDataIfNeeded = () => {
  if (!localStorage.getItem(KEYS.CONTACTS)) {
    localStorage.setItem(KEYS.CONTACTS, JSON.stringify([]));
  }
};

