// --- CANVAS GLOBE COMPONENT ---
const GlobeCanvas = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if(!canvas) return;
        const ctx = canvas.getContext('2d');
        if(!ctx) return;

        let width = canvas.width = canvas.parentElement?.clientWidth || 300;
        let height = canvas.height = canvas.parentElement?.clientHeight || 300;

        let rotation = 0;
        const dots: {x: number, y: number, z: number, r: number}[] = [];
        const DOT_COUNT = 300;
        const RADIUS = Math.min(width, height) * 0.35;

        // Init dots
        for(let i=0; i<DOT_COUNT; i++) {
            const phi = Math.acos(-1 + (2 * i) / DOT_COUNT);
            const theta = Math.sqrt(DOT_COUNT * Math.PI) * phi;
            dots.push({
                x: RADIUS * Math.cos(theta) * Math.sin(phi),
                y: RADIUS * Math.sin(theta) * Math.sin(phi),
                z: RADIUS * Math.cos(phi),
                r: Math.random() * 2
            });
        }

        const animate = () => {
            ctx.clearRect(0, 0, width, height);
            ctx.fillStyle = '#6366F1'; // Primary Color

            rotation += 0.005;

            dots.forEach(dot => {
                // Rotate Y
                const x = dot.x * Math.cos(rotation) - dot.z * Math.sin(rotation);
                const z = dot.z * Math.cos(rotation) + dot.x * Math.sin(rotation);

                // Project 3D to 2D
                const scale = 300 / (300 + z);
                const x2d = (x * scale) + width/2;
                const y2d = (dot.y * scale) + height/2;

                const alpha = Math.max(0, (z + RADIUS) / (2 * RADIUS)); // Fade back dots

                ctx.beginPath();
                ctx.arc(x2d, y2d, dot.r * scale, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(99, 102, 241, ${alpha})`;
                ctx.fill();
            });

            // Draw connection line simulation
            ctx.strokeStyle = `rgba(236, 72, 153, 0.3)`; // Pink secondary
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(width/2, height/2);
            ctx.lineTo(width/2 + 50 * Math.cos(rotation*2), height/2 + 50 * Math.sin(rotation*2));
            ctx.stroke();

            requestAnimationFrame(animate);
        }
        animate();

        return () => {};
    }, []);

    return <canvas ref={canvasRef} className="w-full h-full" />;
}

