                 <h3 className="text-3xl font-bold text-white">{users.length}</h3>
                 <p className="text-slate-400 text-sm">Total Users</p>
             </div>
             <div className="glass-panel p-6 rounded-2xl relative overflow-hidden bg-primary/10 border-primary/20">
                 <div className="absolute top-0 right-0 p-4 opacity-10"><Activity size={64} /></div>
                 <h3 className="text-3xl font-bold text-primary">{users.filter(u => u.plan === 'vip').length}</h3>
                 <p className="text-primary/70 text-sm">VIP Subscribers</p>
