                 <p className="text-slate-400 text-sm">System Uptime</p>
             </div>
        </div>

        {/* GLOBE & REAL TIME VIEW */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="glass-panel rounded-2xl p-1 relative overflow-hidden h-[400px] flex items-center justify-center bg-black/40">
                <div className="absolute top-4 left-4 z-10">
