                    <p>{'>'} Scanning active nodes...</p>
                    <p>{'>'} Encryption protocol: TLS 1.3</p>
                    <p>{'>'} Detected {users.length} active sessions.</p>
                </div>
            </div>

            <div className="glass-panel rounded-2xl p-6 h-[400px] overflow-y-auto">
                <h3 className="text-white font-bold mb-4 flex items-center gap-2"><MapPin size={18} /> User Geo-Location</h3>
                <div className="space-y-3">
                    {users.map((u, i) => (
                        <div key={i} className="flex items-center justify-between p-3 rounded-lg bg-white/5 hover:bg-white/10 transition-colors border border-white/5">
                            <div className="flex items-center gap-3">
                                <div className={`w-2 h-2 rounded-full ${i%2===0 ? 'bg-emerald-500 animate-pulse' : 'bg-slate-500'}`} />
                                <div>
                                    <p className="text-white text-sm font-medium">{u.email}</p>
                                    <p className="text-xs text-slate-400 flex items-center gap-1">
                                        <MapPin size={10} /> {u.location?.city || 'Unknown'}, {u.location?.country || 'N/A'}
                                    </p>
                                </div>
                            </div>
                            <div className="text-right">
                                <p className="text-xs font-mono text-primary bg-primary/10 px-2 py-0.5 rounded">{u.location?.ip || '---'}</p>
                                <p className="text-[10px] text-slate-500 mt-1">{new Date(u.lastActive || '').toLocaleTimeString()}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>

        {/* FULL USER TABLE */}
        <div className="glass-panel rounded-2xl overflow-hidden">
            <div className="p-6 border-b border-white/10">
                <h3 className="text-white font-bold">User Database</h3>
            </div>
            <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="bg-white/5 text-slate-400 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">User</th>
                            <th className="px-6 py-4">Plan</th>
                            <th className="px-6 py-4">Location</th>
                            <th className="px-6 py-4">IP Address</th>
                            <th className="px-6 py-4">Status</th>
                        </tr>
                    </thead>
                    <tbody className="text-sm divide-y divide-white/5">
                        {users.map((u) => (
                            <tr key={u.id} className="hover:bg-white/5 transition-colors">
                                <td className="px-6 py-4">
                                    <div className="font-medium text-white">{u.name}</div>
                                    <div className="text-slate-500 text-xs">{u.email}</div>
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`px-2 py-1 rounded-full text-xs font-bold border ${u.plan === 'vip' ? 'bg-gradient-to-r from-amber-200 to-yellow-400 text-black border-transparent' : 'bg-slate-700 text-slate-300 border-slate-600'}`}>
                                        {u.plan.toUpperCase()}
