            </div>
        </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Search, Plus, Download, Filter, FileText, Trash2, Edit2, 
  Briefcase, User, Users, GraduationCap, Video, HelpCircle,
  Camera, X, Crown, Lock
} from 'lucide-react';
import { Contact, Category, User as UserType } from '../types';
import { getContacts, addContact, deleteContact, logExport, updateContact, upgradeToVip } from '../services/storage';
import { exportToCSV, exportToPDF } from '../utils/export';

interface DashboardProps {
  user: UserType;
}

export const Dashboard: React.FC<DashboardProps> = ({ user }) => {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<Category | 'All'>('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showUpgradeModal, setShowUpgradeModal] = useState(false);
  const [editingContact, setEditingContact] = useState<Contact | null>(null);
  const [upgradeLoading, setUpgradeLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    category: 'Business' as Category,
    note: '',
    avatar: ''
  });

  useEffect(() => {
    loadContacts();
  }, [user.id]);

  const loadContacts = async () => {
    const data = await getContacts(user.id);
    setContacts(data);
  };

  const handleExport = async (type: 'PDF' | 'EXCEL') => {
    if (user.plan === 'free' && type === 'PDF') {
        alert("PDF Export is a VIP Feature. Please upgrade.");
        setShowUpgradeModal(true);
        return;
    }
    await logExport(type, user.id);
    if (type === 'EXCEL') {
        exportToCSV(contacts);
    } else {
        exportToPDF(contacts, user.email);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024 * 2) {
        alert("File too large. Please select an image under 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
        if (editingContact) {
            await updateContact(editingContact.id, { ...formData, user_id: user.id });
        } else {
            await addContact({ ...formData, user_id: user.id }, user.plan);
        }
        setIsModalOpen(false);
        resetForm();
        loadContacts();
    } catch (err: any) {
        if (err.message === 'LIMIT_REACHED') {
            setIsModalOpen(false);
            setShowUpgradeModal(true);
        }
    }
  };

  const handleUpgrade = async () => {
      setUpgradeLoading(true);
      await upgradeToVip(user.id);
      window.location.reload(); // Quick way to refresh session state in this demo
  };

  const resetForm = () => {
    setEditingContact(null);
    setFormData({ name: '', email: '', phone: '', category: 'Business', note: '', avatar: '' });
  };

  const handleEdit = (contact: Contact) => {
      setEditingContact(contact);
      setFormData({
          name: contact.name,
          email: contact.email,
          phone: contact.phone,
          category: contact.category,
          note: contact.note,
          avatar: contact.avatar || ''
      });
      setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
      if(confirm('Are you sure you want to remove this connection from your secure vault?')) {
        await deleteContact(id);
        loadContacts();
      }
  };

  const filteredContacts = useMemo(() => {
    return contacts.filter(c => {
      const matchesSearch = c.name.toLowerCase().includes(search.toLowerCase()) || 
                            c.email.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = filterCategory === 'All' || c.category === filterCategory;
      return matchesSearch && matchesCategory;
    });
  }, [contacts, search, filterCategory]);

  const CategoryIcon = ({ category }: { category: Category }) => {
      switch(category) {
          case 'Business': return <Briefcase size={14} className="text-blue-400" />;
          case 'Family': return <Users size={14} className="text-green-400" />;
          case 'Student': return <GraduationCap size={14} className="text-yellow-400" />;
          case 'Creator': return <Video size={14} className="text-purple-400" />;
          case 'Friends': return <User size={14} className="text-pink-400" />;
          default: return <HelpCircle size={14} className="text-slate-400" />;
      }
  };

  return (
    <div className="space-y-6 animate-slide-up relative">

      {/* Banner for Free Users */}
      {user.plan === 'free' && (
          <div className="bg-gradient-to-r from-indigo-900 to-purple-900 border border-white/10 rounded-2xl p-4 flex items-center justify-between shadow-xl">
              <div className="flex items-center gap-3">
                  <div className="p-2 bg-white/10 rounded-lg"><Crown className="text-yellow-400" size={24} /></div>
                  <div>
                      <h4 className="font-bold text-white">Unlock VIP Power</h4>
                      <p className="text-xs text-slate-300">You are on the Free Plan (Max 5 contacts). Upgrade for unlimited access.</p>
                  </div>
              </div>
              <button 
                onClick={() => setShowUpgradeModal(true)}
                className="bg-white text-indigo-900 px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-100 transition-colors"
              >
                  Upgrade
              </button>
          </div>
      )}

      {/* Header Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group hover:bg-white/5 transition-colors">
            <div className="absolute right-0 top-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity transform group-hover:scale-110 duration-500">
                <Users size={60} className="text-white dark:text-white text-slate-700" />
            </div>
            <p className="text-slate-400 text-sm font-medium mb-1">Total Network</p>
            <h3 className="text-3xl font-bold text-white dark:text-white text-slate-800 tracking-tight">{contacts.length} {user.plan==='free' && <span className="text-lg text-slate-500 font-normal">/ 5</span>}</h3>
            <p className="text-xs text-emerald-400 mt-2 flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                Securely Stored
            </p>
        </div>
        <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group hover:bg-white/5 transition-colors">
            <div className="absolute right-0 top-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity transform group-hover:scale-110 duration-500">
                <Briefcase size={60} className="text-white dark:text-white text-slate-700" />
            </div>
            <p className="text-slate-400 text-sm font-medium mb-1">Business Contacts</p>
            <h3 className="text-3xl font-bold text-white dark:text-white text-slate-800 tracking-tight">{contacts.filter(c => c.category === 'Business').length}</h3>
            <p className="text-xs text-primary mt-2">High Value Targets</p>
        </div>
        <div className="glass-panel p-6 bg-gradient-to-br from-primary/20 to-purple-900/20 rounded-2xl relative overflow-hidden border-primary/20 hover:border-primary/40 transition-colors">
             <div className="flex flex-col h-full justify-between">
                <div>
                    <h3 className="text-white font-bold text-lg">Growth Engine</h3>
                    <p className="text-slate-300 text-xs mt-1">Your network is your net worth.</p>
                </div>
                <button 
                    onClick={() => {
                        resetForm();
                        setIsModalOpen(true);
                    }}
                    className="mt-4 w-full bg-white text-primary font-bold py-2.5 rounded-lg hover:bg-slate-100 transition-all flex items-center justify-center gap-2 shadow-lg shadow-black/20 transform active:scale-95"
                >
                    <Plus size={18} /> Add Contact
                </button>
             </div>
        </div>
      </div>

      {/* Controls */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between glass-panel p-4 rounded-2xl sticky top-2 z-30 backdrop-blur-xl">
        <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
            <input 
                type="text"
                placeholder="Search name, email..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full bg-slate-900/50 dark:bg-slate-900/50 bg-slate-100 border border-slate-700 dark:border-slate-700 border-slate-200 rounded-xl pl-12 pr-4 py-2.5 text-white dark:text-white text-slate-900 placeholder-slate-500 focus:outline-none focus:border-primary/50 transition-colors"
            />
        </div>

        <div className="flex items-center gap-3 w-full md:w-auto">
             <div className="relative group w-full md:w-auto">
                <select 
                    value={filterCategory}
                    onChange={(e) => setFilterCategory(e.target.value as Category | 'All')}
                    className="w-full md:w-auto appearance-none bg-slate-900/50 dark:bg-slate-900/50 bg-slate-100 border border-slate-700 dark:border-slate-700 border-slate-200 text-slate-300 dark:text-slate-300 text-slate-700 pl-4 pr-10 py-2.5 rounded-xl focus:outline-none focus:border-primary/50 cursor-pointer"
                >
                    <option value="All">All Categories</option>
                    <option value="Business">Business</option>
                    <option value="Creator">Creator</option>
                    <option value="Student">Student</option>
                    <option value="Family">Family</option>
                    <option value="Friends">Friends</option>
                    <option value="Other">Other</option>
                </select>
                <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={16} />
             </div>

             <div className="flex gap-2">
                 <button onClick={() => handleExport('EXCEL')} className="p-2.5 bg-slate-800 hover:bg-slate-700 dark:bg-slate-800 dark:hover:bg-slate-700 bg-slate-200 hover:bg-slate-300 text-emerald-400 dark:text-emerald-400 text-emerald-600 rounded-xl transition-colors tooltip-trigger border border-slate-700 dark:border-slate-700 border-slate-300 hover:border-emerald-500/50" title="Export CSV">
                    <FileText size={20} />
                 </button>
                 <button onClick={() => handleExport('PDF')} className={`p-2.5 rounded-xl transition-colors tooltip-trigger border ${user.plan === 'free' ? 'bg-slate-900 text-slate-600 border-slate-800 cursor-not-allowed' : 'bg-slate-800 text-rose-400 border-slate-700 hover:border-rose-500/50'}`} title="Export PDF">
                    {user.plan === 'free' ? <Lock size={20} /> : <Download size={20} />}
                 </button>
             </div>
        </div>
      </div>

      {/* List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredContacts.map((contact, idx) => (
            <div 
                key={contact.id} 
                className="glass-panel p-5 rounded-2xl hover:border-primary/30 transition-all group relative animate-slide-up"
                style={{ animationDelay: `${idx * 50}ms` }}
            >
                <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-4">
                        <div className="relative">
                            {contact.avatar ? (
                                <img 
                                    src={contact.avatar} 
                                    alt={contact.name} 
                                    className="w-14 h-14 rounded-full object-cover border-2 border-white/10 shadow-lg group-hover:scale-105 transition-transform duration-300"
                                />
                            ) : (
                                <div className="w-14 h-14 rounded-full bg-gradient-to-br from-slate-700 to-slate-800 flex items-center justify-center text-white font-bold text-xl border border-white/10 shadow-lg group-hover:scale-105 transition-transform duration-300">
                                    {contact.name.charAt(0).toUpperCase()}
                                </div>
                            )}
                            <div className="absolute -bottom-1 -right-1 w-5 h-5 bg-background rounded-full flex items-center justify-center">
                                <CategoryIcon category={contact.category} />
                            </div>
                        </div>

                        <div className="flex-1 min-w-0">
                            <h4 className="font-bold text-white dark:text-white text-slate-800 text-lg truncate">{contact.name}</h4>
                            <span className={`inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full border mt-1 ${
                                contact.category === 'Business' ? 'bg-blue-500/10 text-blue-300 border-blue-500/20' :
                                contact.category === 'Creator' ? 'bg-purple-500/10 text-purple-300 border-purple-500/20' :
                                'bg-slate-700/50 text-slate-400 border-slate-600'
                            }`}>
                               {contact.category}
                            </span>
                        </div>
                    </div>

                    <div className="flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity translate-x-2 group-hover:translate-x-0">
                         <button onClick={() => handleEdit(contact)} className="p-2 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white transition-colors">
                            <Edit2 size={16} />
                         </button>
                         <button onClick={() => handleDelete(contact.id)} className="p-2 hover:bg-rose-500/20 rounded-lg text-slate-400 hover:text-rose-400 transition-colors">
                            <Trash2 size={16} />
                         </button>
                    </div>
                </div>

                <div className="space-y-3 mt-4 pt-4 border-t border-white/5">
                    {contact.email && (
                        <div className="flex items-center gap-3 text-sm text-slate-400 group-hover:text-slate-300 transition-colors">
                            <div className="p-1.5 rounded-md bg-white/5">
                                <Mail size={14} />
                            </div>
                            <a href={`mailto:${contact.email}`} className="hover:text-primary truncate transition-colors">{contact.email}</a>
                        </div>
                    )}
                    {contact.phone && (
                         <div className="flex items-center gap-3 text-sm text-slate-400 group-hover:text-slate-300 transition-colors">
                            <div className="p-1.5 rounded-md bg-white/5">
                                <Phone size={14} />
                            </div>
                            <a href={`tel:${contact.phone}`} className="hover:text-primary transition-colors">{contact.phone}</a>
                        </div>
                    )}
                    {contact.note && (
                        <div className="mt-3 text-xs text-slate-500 italic bg-black/20 p-3 rounded-xl border border-white/5">
                            "{contact.note}"
                        </div>
                    )}
                </div>
            </div>
        ))}

        {filteredContacts.length === 0 && (
            <div className="col-span-full py-16 text-center text-slate-500 border border-dashed border-white/10 rounded-3xl bg-white/5/50">
                <div className="w-20 h-20 mx-auto bg-slate-800/50 rounded-full flex items-center justify-center mb-6 animate-pulse-slow">
                    <Users size={32} className="opacity-50" />
                </div>
                <h3 className="text-white dark:text-white text-slate-800 font-semibold text-lg mb-2">Your network is empty</h3>
                <p className="max-w-xs mx-auto mb-6">Start building your net worth by adding your first important connection.</p>
                <button 
                    onClick={() => {
                        resetForm();
                        setIsModalOpen(true);
                    }}
                    className="text-primary hover:text-white font-semibold transition-colors flex items-center justify-center gap-2 mx-auto"
                >
                    <Plus size={16} /> Add First Contact
                </button>
            </div>
        )}
      </div>

      {/* Add/Edit Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md transition-opacity">
            <div className="glass-panel w-full max-w-lg rounded-2xl p-6 border border-white/10 animate-fade-in shadow-2xl shadow-primary/10">
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-xl font-bold text-white flex items-center gap-2">
                        {editingContact ? <Edit2 size={20} className="text-primary" /> : <Plus size={20} className="text-primary" />}
                        {editingContact ? 'Edit Contact' : 'New Connection'}
                    </h2>
                    <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-white p-1 hover:bg-white/10 rounded-lg transition-colors">
                        <X size={24} />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="space-y-5">
                    {/* ... Form fields ... */}
                    {/* Photo Upload */}
                    <div className="flex items-center gap-4 mb-6">
                         <div 
                            className="w-20 h-20 rounded-full bg-slate-800 border-2 border-dashed border-slate-600 flex items-center justify-center overflow-hidden relative group cursor-pointer hover:border-primary transition-colors"
                            onClick={() => fileInputRef.current?.click()}
                         >
                             {formData.avatar ? (
                                <img src={formData.avatar} className="w-full h-full object-cover" alt="Preview" />
                             ) : (
                                <Camera className="text-slate-500 group-hover:text-primary transition-colors" />
                             )}
                         </div>
                         <div className="flex-1">
                             <h4 className="text-sm font-medium text-white">Profile Photo</h4>
                             <p className="text-xs text-slate-400 mb-2">Supports JPG, PNG (Max 2MB)</p>
                             <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                             <button type="button" onClick={() => fileInputRef.current?.click()} className="text-xs bg-white/10 hover:bg-white/20 text-white px-3 py-1.5 rounded-lg transition-colors">Upload Image</button>
                         </div>
                    </div>
                    {/* Standard Inputs */}
                    <div>
                        <label className="block text-xs font-medium text-slate-400 mb-1.5 uppercase tracking-wider">Full Name</label>
                        <input required type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full glass-input rounded-xl px-4 py-3 text-sm" placeholder="e.g. Elon Musk" />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full glass-input rounded-xl px-4 py-3 text-sm" placeholder="Email" />
                        <input type="text" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full glass-input rounded-xl px-4 py-3 text-sm" placeholder="Phone" />
                    </div>
                    <div>
                        <label className="block text-xs font-medium text-slate-400 mb-1.5 uppercase tracking-wider">Category</label>
                        <div className="grid grid-cols-3 gap-2">
                            {['Business', 'Creator', 'Student', 'Family', 'Friends', 'Other'].map(cat => (
                                <button type="button" key={cat} onClick={() => setFormData({...formData, category: cat as Category})} className={`text-xs py-2.5 rounded-lg border transition-all ${formData.category === cat ? 'bg-primary/20 border-primary text-white' : 'border-slate-700 text-slate-400'}`}>{cat}</button>
                            ))}
                        </div>
                    </div>
                    <div>
                         <label className="block text-xs font-medium text-slate-400 mb-1.5 uppercase tracking-wider">Secure Note</label>
                         <textarea value={formData.note} onChange={e => setFormData({...formData, note: e.target.value})} className="w-full glass-input rounded-xl px-4 py-3 min-h-[80px] text-sm resize-none" placeholder="Notes..." />
                    </div>

                    <div className="pt-2">
                        <button type="submit" className="w-full bg-gradient-to-r from-primary to-accent py-3.5 rounded-xl font-bold text-white shadow-lg">
                            {editingContact ? 'Save Changes' : 'Secure Connection'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
      )}

      {/* Upgrade Modal */}
      {showUpgradeModal && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-fade-in">
              <div className="glass-panel w-full max-w-md rounded-3xl p-8 border-2 border-primary/50 relative overflow-hidden text-center">
                  <button onClick={() => setShowUpgradeModal(false)} className="absolute top-4 right-4 text-slate-400 hover:text-white"><X size={24} /></button>

                  <div className="absolute top-[-20%] left-[-20%] w-64 h-64 bg-primary/20 rounded-full blur-[80px]" />

                  <Crown size={64} className="text-yellow-400 mx-auto mb-6 drop-shadow-[0_0_15px_rgba(250,204,21,0.5)]" />
                  <h2 className="text-3xl font-bold text-white mb-2">VContact Premium</h2>
                  <p className="text-slate-300 mb-8">Unlock the full potential of your network.</p>

                  <div className="space-y-4 mb-8 text-left">
                      <div className="flex items-center gap-3">
                          <div className="bg-emerald-500/20 p-1 rounded text-emerald-400"><Briefcase size={16} /></div>
                          <span className="text-white">Unlimited Contacts</span>
                      </div>
                      <div className="flex items-center gap-3">
                          <div className="bg-rose-500/20 p-1 rounded text-rose-400"><FileText size={16} /></div>
                          <span className="text-white">PDF & Excel Exports</span>
                      </div>
                      <div className="flex items-center gap-3">
                          <div className="bg-purple-500/20 p-1 rounded text-purple-400"><Lock size={16} /></div>
                          <span className="text-white">Advanced Encryption</span>
                      </div>
                  </div>

                  <div className="bg-white/5 rounded-xl p-4 mb-8">
                      <p className="text-sm text-slate-400 uppercase tracking-wider mb-1">Monthly Plan</p>
                      <div className="flex items-end justify-center gap-1">
                          <span className="text-4xl font-bold text-white">€2.99</span>
                          <span className="text-slate-400 mb-1">/mo</span>
                      </div>
                  </div>

                  <button 
                    onClick={handleUpgrade}
                    disabled={upgradeLoading}
                    className="w-full bg-gradient-to-r from-yellow-400 to-amber-600 text-black font-bold py-4 rounded-xl shadow-lg hover:shadow-yellow-400/20 transition-all transform hover:-translate-y-1 active:scale-95 disabled:opacity-50"
                  >
                      {upgradeLoading ? 'Processing Payment...' : 'Unlock Premium Access'}
                  </button>
                  <p className="text-xs text-slate-500 mt-4">Secure payment via Stripe. Cancel anytime.</p>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useMemo } from 'react';
