import React, { useState, useEffect } from 'react';
import { Auth } from './components/Auth';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { AdminDashboard } from './components/AdminDashboard';
import { Profile } from './components/Profile';
import { getCurrentUser, login, logout, seedDataIfNeeded, deleteAccount } from './services/storage';
import { User } from './types';

interface Ripple {
  id: number;
  x: number;
  y: number;
}

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState('dashboard'); // 'dashboard', 'stats', 'profile'
  const [loading, setLoading] = useState(true);

  // Ripple Effect State
  const [ripples, setRipples] = useState<Ripple[]>([]);

  useEffect(() => {
    // Check local storage for session
    const storedUser = getCurrentUser();
    if (storedUser) {
      setUser(storedUser);
    }
    seedDataIfNeeded();
    setLoading(false);
  }, []);

  // Theme & Language Effect Engine
  useEffect(() => {
      const root = window.document.documentElement;

      // Theme Logic
      root.classList.remove('light', 'dark');
      const themePreference = user?.preferences?.theme || 'dark';

      if (themePreference === 'system') {
          const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
          root.classList.add(systemTheme);
      } else {
          root.classList.add(themePreference);
      }

      // Language Logic
      // We don't rely solely on the HTML tag, we pass the prop, 
      // but setting the tag is good practice.
      root.setAttribute('lang', user?.preferences?.language || 'en');

  }, [user?.preferences?.theme, user?.preferences?.language]);

  // Global Pointer Listener for Echo Effect
  useEffect(() => {
    const handlePointerDown = (e: PointerEvent) => {
      setRipples(prev => {
        if (prev.length > 5) return prev.slice(1);
        return prev;
      });

      const newRipple = {
        id: Date.now(),
        x: e.clientX,
        y: e.clientY
      };

      setRipples(prev => [...prev, newRipple]);

      setTimeout(() => {
        setRipples(prev => prev.filter(r => r.id !== newRipple.id));
      }, 600);
    };

    window.addEventListener('pointerdown', handlePointerDown);
    return () => window.removeEventListener('pointerdown', handlePointerDown);
  }, []);

  const handleLogin = async (email: string, password?: string) => {
    const newUser = await login(email, password);
    setUser(newUser);
    setView('dashboard');
  };

  const handleLogout = async () => {
    await logout();
    setUser(null);
  };

  const handleDeleteAccount = async () => {
      if (user) {
          setLoading(true);
          await deleteAccount(user.id);
          setUser(null);
          setLoading(false);
      }
  };

  const handleUpdateUser = (updatedUser: User) => {
      setUser(prev => ({...updatedUser}));
  };

  const currentLang = user?.preferences?.language === 'fr' ? 'fr' : 'en';

  const renderContent = () => {
    switch (view) {
      case 'dashboard':
        return <Dashboard user={user!} lang={currentLang} />;
      case 'stats':
        // Explicitly check role here for security, though Layout handles menu visibility
        return user?.role === 'admin' ? <AdminDashboard lang={currentLang} /> : <div className="text-slate-900 dark:text-white p-4">Access Restricted</div>;
      case 'profile':
        return <Profile user={user!} onUpdate={handleUpdateUser} onDelete={handleDeleteAccount} lang={currentLang} />;
      default:
        return <Dashboard user={user!} lang={currentLang} />;
    }
  };

  if (loading) return (
      <div className="min-h-screen bg-slate-50 dark:bg-[#0B0F19] flex items-center justify-center">
          <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
  );

  return (
    <>
      {/* Global Echo FX Layer */}
      <div className="fixed inset-0 pointer-events-none z-[9999] overflow-hidden">
        {ripples.map(ripple => (
          <div
            key={ripple.id}
            className="absolute rounded-full border-2 border-primary/40 bg-primary/10 animate-ripple shadow-[0_0_15px_rgba(99,102,241,0.5)]"
            style={{
              left: ripple.x,
              top: ripple.y,
              width: '20px',
              height: '20px',
              marginLeft: '-10px',
              marginTop: '-10px',
            }}
          />
        ))}
      </div>

      {!user ? (
        <Auth onLogin={handleLogin} />
      ) : (
        <Layout user={user} onLogout={handleLogout} currentPage={view} onNavigate={setView} lang={currentLang}>
          {renderContent()}
        </Layout>
      )}
    </>
  );
}

export default App;

