import React, { useState, useRef, useEffect } from 'react';
import { User as UserIcon, Shield, Camera, Save, Bell, Globe, Trash2, Download, Moon, Sun, Monitor, CheckCircle } from 'lucide-react';
import { User } from '../types';
import { updateUser } from '../services/storage';
import { translations } from '../utils/translations';

interface ProfileProps {
  user: User;
  onUpdate: (updatedUser: User) => void;
  onDelete: () => void;
  lang: 'en' | 'fr';
}

export const Profile: React.FC<ProfileProps> = ({ user, onUpdate, onDelete, lang }) => {
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'general' | 'preferences' | 'data'>('general');
  const [successMsg, setSuccessMsg] = useState('');
  const t = translations[lang].profile;

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: user?.name || '',
    title: user?.title || '',
    avatar: user?.avatar || '',
    notifications: user?.preferences?.notifications ?? true,
    publicProfile: user?.preferences?.publicProfile ?? false,
    theme: user?.preferences?.theme ?? 'dark',
    language: user?.preferences?.language ?? 'en'
  });

  useEffect(() => {
    if (user) {
        setFormData(prev => ({
            ...prev,
            name: user.name || '',
            title: user.title || '',
            avatar: user.avatar || '',
            notifications: user.preferences?.notifications ?? true,
            publicProfile: user.preferences?.publicProfile ?? false,
            theme: user.preferences?.theme ?? 'dark',
            language: user.preferences?.language ?? 'en'
        }));
    }
  }, [user]);

  // Immediate setting handler for instant UI feedback
  const handleSettingChange = async (key: string, value: any) => {
      // Update local form state immediately
      const newFormData = { ...formData, [key]: value };
      setFormData(newFormData);

      // Save to storage immediately for preferences (Theme/Lang)
      try {
          const updated = await updateUser({
              preferences: {
                  theme: newFormData.theme as any,
                  notifications: newFormData.notifications,
                  publicProfile: newFormData.publicProfile,
                  language: newFormData.language as any
              }
          });
          // Notify parent to trigger App.tsx useEffect
          onUpdate(updated);
      } catch (e) {
          console.error("Failed to quick save preference");
      }
  };

  const handleSave = async () => {
    setLoading(true);
    try {
        const updated = await updateUser({
            name: formData.name,
            title: formData.title,
            avatar: formData.avatar,
            preferences: {
                theme: formData.theme as any,
                notifications: formData.notifications,
                publicProfile: formData.publicProfile,
                language: formData.language as any
            }
        });
        onUpdate(updated);
        setSuccessMsg('Profile updated successfully');
        setTimeout(() => setSuccessMsg(''), 3000);
    } catch (e) {
        console.error("Failed to update profile", e);
        setSuccessMsg('Error updating profile');
    } finally {
        setLoading(false);
    }
  };

  const handleDeleteAccount = () => {
      const confirmed = window.confirm(
          "DANGER: Are you sure you want to delete your account?\n\nThis will permanently delete all your contacts and data. This action cannot be undone."
      );
      if (confirmed) {
          const doubleCheck = window.confirm("Please confirm one last time to delete your account permanently.");
          if (doubleCheck) {
              onDelete();
          }
      }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024 * 2) {
        alert("File too large. Please select an image under 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  if (!user) return <div className="text-slate-900 dark:text-white">Loading profile...</div>;

  return (
    <div className="max-w-4xl mx-auto space-y-6 animate-fade-in pb-24 relative z-10">

        {/* Header Profile Card */}
        <div className="glass-panel p-6 md:p-8 rounded-3xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-r from-primary/30 via-secondary/30 to-accent/30"></div>

            <div className="relative z-10 flex flex-col md:flex-row items-end md:items-center gap-6 mt-12">
                <div className="relative group mx-auto md:mx-0">
                    <div className="w-32 h-32 rounded-3xl bg-slate-100 dark:bg-[#0B0F19] p-1.5 shadow-2xl">
                        <div className="w-full h-full rounded-2xl overflow-hidden bg-slate-200 dark:bg-slate-800 flex items-center justify-center relative">
                            {formData.avatar ? (
                                <img src={formData.avatar} alt="Profile" className="w-full h-full object-cover" />
                            ) : (
                                <UserIcon size={48} className="text-slate-400 dark:text-slate-500" />
                            )}
                            <div 
