interface LayoutProps {
  children: React.ReactNode;
  user: User | null;
  onLogout: () => void;
  currentPage: string;
  onNavigate: (page: string) => void;
  lang: 'en' | 'fr';
  onAdminAuth?: (password: string) => Promise<boolean>; // New prop for elevating privilege
}

export const Layout: React.FC<LayoutProps> = ({ children, user, onLogout, currentPage, onNavigate, lang, onAdminAuth }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState(false);
  const [adminPass, setAdminPass] = useState('');
  const [adminError, setAdminError] = useState(false);
  const t = translations[lang].nav;
  const tModal = translations[lang].adminModal;

  const NavItem = useMemo(() => {
    return ({ id, icon: Icon, label, adminOnly = false }: any) => {
      // If adminOnly is true, only show if user is admin
      if (adminOnly && user?.role !== 'admin') return null;

      const isActive = currentPage === id;
      return (
        <button
          onClick={() => {
            onNavigate(id);
            setIsMobileMenuOpen(false);
          }}
          className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 group relative overflow-hidden cursor-pointer ${
            isActive 
              ? 'bg-primary/20 text-primary dark:text-white border border-primary/30 shadow-[0_0_15px_rgba(99,102,241,0.3)]' 
              : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-black/5 dark:hover:bg-white/5'
          }`}
        >
          <Icon size={20} className={`${isActive ? 'text-primary' : 'text-slate-400 group-hover:text-primary'} transition-colors relative z-10`} />
          <span className="font-medium relative z-10">{label}</span>
          {isActive && <div className="ml-auto w-1.5 h-1.5 rounded-full bg-primary shadow-[0_0_8px_#6366F1] relative z-10" />}
          {isActive && <div className="absolute inset-0 bg-gradient-to-r from-primary/10 to-transparent opacity-50" />}
        </button>
      );
    };
  }, [currentPage, onNavigate, user?.role]);

  const handleAdminSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setAdminError(false);
      if (onAdminAuth) {
          const success = await onAdminAuth(adminPass);
          if (success) {
              setIsAdminModalOpen(false);
              setAdminPass('');
              onNavigate('stats'); // Navigate to Admin Dashboard on success
          } else {
              setAdminError(true);
          }
      }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0B0F19] transition-colors duration-300 flex overflow-hidden selection:bg-primary/30 selection:text-white">
