import React, { useState, useEffect } from 'react';
import { Auth } from './components/Auth';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { AdminDashboard } from './components/AdminDashboard';
import { Profile } from './components/Profile';
import { Subscription } from './components/Subscription';
import { FAQ } from './components/FAQ';
import { getCurrentUser, login, logout, seedDataIfNeeded, deleteAccount } from './services/storage';
import { User } from './types';

interface Ripple {
  id: number;
  x: number;
  y: number;
}

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState('dashboard'); // 'dashboard', 'stats', 'profile', 'subscription', 'faq'
  const [loading, setLoading] = useState(true);

  // Ripple Effect State
  const [ripples, setRipples] = useState<Ripple[]>([]);

  useEffect(() => {
    // Check local storage for session
    const storedUser = getCurrentUser();
    if (storedUser) {
      setUser(storedUser);
    }
    seedDataIfNeeded();
    setLoading(false);
  }, []);

  // Theme & Language Effect Engine
  useEffect(() => {
      const root = window.document.documentElement;

      // Theme Logic
      root.classList.remove('light', 'dark');
      const themePreference = user?.preferences?.theme || 'dark';

      if (themePreference === 'system') {
          const systemTheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
          root.classList.add(systemTheme);
      } else {
          root.classList.add(themePreference);
      }

      // Language Logic
      root.setAttribute('lang', user?.preferences?.language || 'en');

  }, [user?.preferences?.theme, user?.preferences?.language]);

  // Global Pointer Listener for Echo Effect
  useEffect(() => {
    const handlePointerDown = (e: PointerEvent) => {
      setRipples(prev => {
        if (prev.length > 5) return prev.slice(1);
        return prev;
      });

      const newRipple = {
        id: Date.now(),
        x: e.clientX,
        y: e.clientY
      };

      setRipples(prev => [...prev, newRipple]);

      setTimeout(() => {
        setRipples(prev => prev.filter(r => r.id !== newRipple.id));
      }, 600);
    };

    window.addEventListener('pointerdown', handlePointerDown);
    return () => window.removeEventListener('pointerdown', handlePointerDown);
  }, []);

  const handleLogin = async (email: string, password?: string) => {
    const newUser = await login(email, password);
    setUser(newUser);
    setView('dashboard');
  };

  const handleAdminAuthAttempt = async (password: string): Promise<boolean> => {
      if (!user) return false;
      // Re-use login logic to verify admin pass without changing email
      try {
          // Attempt login with current email + admin password
          // The mock login function handles the password check for ADMIN_PASS
          const checkUser = await login(user.email, password);
          if (checkUser.role === 'admin') {
              setUser(checkUser); // Upgrade session to admin
              return true;
          }
          return false;
      } catch (e) {
          return false;
      }
  };

  const handleLogout = async () => {
    await logout();
    setUser(null);
  };

  const handleDeleteAccount = async () => {
      if (user) {
          setLoading(true);
          await deleteAccount(user.id);
          setUser(null);
          setLoading(false);
      }
  };

  const handleUpdateUser = (updatedUser: User) => {
      setUser(prev => ({...updatedUser}));
  };

  const currentLang = user?.preferences?.language === 'fr' ? 'fr' : 'en';

  const renderContent = () => {
    switch (view) {
      case 'dashboard':
        return <Dashboard user={user!} lang={currentLang} />;
      case 'stats':
        return user?.role === 'admin' ? <AdminDashboard lang={currentLang} /> : <div className="text-slate-900 dark:text-white p-4">Access Restricted</div>;
      case 'profile':
        return <Profile user={user!} onUpdate={handleUpdateUser} onDelete={handleDeleteAccount} lang={currentLang} />;
      case 'subscription':
        return <Subscription user={user!} lang={currentLang} onUpgrade={handleUpdateUser} />;
      case 'faq':
        return <FAQ lang={currentLang} />;
      default:
        return <Dashboard user={user!} lang={currentLang} />;
    }
  };

  if (loading) return (
      <div className="min-h-screen bg-slate-50 dark:bg-[#0B0F19] flex items-center justify-center">
          <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
  );

  return (
    <>
      {/* Global Echo FX Layer */}
      <div className="fixed inset-0 pointer-events-none z-[9999] overflow-hidden">
        {ripples.map(ripple => (
          <div
            key={ripple.id}
            className="absolute rounded-full border-2 border-primary/40 bg-primary/10 animate-ripple shadow-[0_0_15px_rgba(99,102,241,0.5)]"
            style={{
              left: ripple.x,
              top: ripple.y,
              width: '20px',
              height: '20px',
              marginLeft: '-10px',
              marginTop: '-10px',
            }}
          />
        ))}
      </div>

      {!user ? (
        <Auth onLogin={handleLogin} />
      ) : (
        <Layout 
            user={user} 
            onLogout={handleLogout} 
            currentPage={view} 
            onNavigate={setView} 
            lang={currentLang}
            onAdminAuth={handleAdminAuthAttempt}
        >
          {renderContent()}
        </Layout>
      )}
    </>
  );
}

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { getAllUsers } from '../services/storage';
import { User } from '../types';
import { Target, Users, MapPin, Globe as GlobeIcon, Activity, Lock, TrendingUp, DollarSign, Terminal } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

// --- CANVAS GLOBE COMPONENT ---
const GlobeCanvas = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if(!canvas) return;
        const ctx = canvas.getContext('2d');
        if(!ctx) return;

        let width = canvas.width = canvas.parentElement?.clientWidth || 300;
        let height = canvas.height = canvas.parentElement?.clientHeight || 300;

        let rotation = 0;
        const dots: {x: number, y: number, z: number, r: number}[] = [];
        const DOT_COUNT = 300;
        const RADIUS = Math.min(width, height) * 0.35;

        // Init dots
        for(let i=0; i<DOT_COUNT; i++) {
            const phi = Math.acos(-1 + (2 * i) / DOT_COUNT);
            const theta = Math.sqrt(DOT_COUNT * Math.PI) * phi;
            dots.push({
                x: RADIUS * Math.cos(theta) * Math.sin(phi),
                y: RADIUS * Math.sin(theta) * Math.sin(phi),
                z: RADIUS * Math.cos(phi),
                r: Math.random() * 2
            });
        }

        const animate = () => {
            ctx.clearRect(0, 0, width, height);
            ctx.fillStyle = '#6366F1'; // Primary Color

            rotation += 0.005;

            dots.forEach(dot => {
                // Rotate Y
                const x = dot.x * Math.cos(rotation) - dot.z * Math.sin(rotation);
                const z = dot.z * Math.cos(rotation) + dot.x * Math.sin(rotation);

                // Project 3D to 2D
                const scale = 300 / (300 + z);
                const x2d = (x * scale) + width/2;
                const y2d = (dot.y * scale) + height/2;

                const alpha = Math.max(0, (z + RADIUS) / (2 * RADIUS)); // Fade back dots

                ctx.beginPath();
                ctx.arc(x2d, y2d, dot.r * scale, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(99, 102, 241, ${alpha})`;
                ctx.fill();
            });

            // Draw connection line simulation
            ctx.strokeStyle = `rgba(236, 72, 153, 0.3)`; // Pink secondary
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(width/2, height/2);
            ctx.lineTo(width/2 + 50 * Math.cos(rotation*2), height/2 + 50 * Math.sin(rotation*2));
            ctx.stroke();

            requestAnimationFrame(animate);
        }
        animate();

        return () => {};
    }, []);

    return <canvas ref={canvasRef} className="w-full h-full" />;
}

