import React, { useState, useRef, useEffect } from 'react';
import { User as UserIcon, Shield, Camera, Save, Bell, Globe, Trash2, Download, Moon, Sun, Monitor, CheckCircle } from 'lucide-react';
import { User } from '../types';
import { updateUser } from '../services/storage';
import { translations } from '../utils/translations';

interface ProfileProps {
  user: User;
  onUpdate: (updatedUser: User) => void;
  onDelete: () => void;
  lang: 'en' | 'fr';
}

export const Profile: React.FC<ProfileProps> = ({ user, onUpdate, onDelete, lang }) => {
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'general' | 'preferences' | 'data'>('general');
  const [successMsg, setSuccessMsg] = useState('');
  const t = translations[lang].profile;

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: user?.name || '',
    title: user?.title || '',
    avatar: user?.avatar || '',
    notifications: user?.preferences?.notifications ?? true,
    publicProfile: user?.preferences?.publicProfile ?? false,
    theme: user?.preferences?.theme ?? 'dark',
    language: user?.preferences?.language ?? 'en'
  });

  useEffect(() => {
    if (user) {
        setFormData(prev => ({
            ...prev,
            name: user.name || '',
            title: user.title || '',
            avatar: user.avatar || '',
            notifications: user.preferences?.notifications ?? true,
            publicProfile: user.preferences?.publicProfile ?? false,
            theme: user.preferences?.theme ?? 'dark',
            language: user.preferences?.language ?? 'en'
        }));
    }
  }, [user]);

  // Immediate setting handler for instant UI feedback
  const handleSettingChange = async (key: string, value: any) => {
      // Update local form state immediately
      const newFormData = { ...formData, [key]: value };
      setFormData(newFormData);

      // Save to storage immediately for preferences (Theme/Lang)
      try {
          const updated = await updateUser({
              preferences: {
                  theme: newFormData.theme as any,
                  notifications: newFormData.notifications,
                  publicProfile: newFormData.publicProfile,
                  language: newFormData.language as any
              }
          });
          // Notify parent to trigger App.tsx useEffect
          onUpdate(updated);
      } catch (e) {
          console.error("Failed to quick save preference");
      }
  };

  const handleSave = async () => {
    setLoading(true);
    try {
        const updated = await updateUser({
            name: formData.name,
            title: formData.title,
            avatar: formData.avatar,
            preferences: {
                theme: formData.theme as any,
                notifications: formData.notifications,
                publicProfile: formData.publicProfile,
                language: formData.language as any
            }
        });
        onUpdate(updated);
        setSuccessMsg('Profile updated successfully');
        setTimeout(() => setSuccessMsg(''), 3000);
    } catch (e) {
        console.error("Failed to update profile", e);
        setSuccessMsg('Error updating profile');
    } finally {
        setLoading(false);
    }
  };

  const handleDeleteAccount = () => {
      const confirmed = window.confirm(
          "DANGER: Are you sure you want to delete your account?\n\nThis will permanently delete all your contacts and data. This action cannot be undone."
      );
      if (confirmed) {
          const doubleCheck = window.confirm("Please confirm one last time to delete your account permanently.");
          if (doubleCheck) {
              onDelete();
          }
      }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024 * 2) {
        alert("File too large. Please select an image under 2MB.");
        return;
      }
      const reader = new FileReader();

      reader.onloadend = async () => {
        const base64String = reader.result as string;

        // 1. Update Local State immediately for preview
        setFormData(prev => ({ ...prev, avatar: base64String }));

        // 2. Save to Storage Immediately
        // This prevents the image from reverting if the user toggles a switch (like theme)
        // before hitting the main "Save" button, as toggles trigger a re-sync with user props.
        try {
             const updated = await updateUser({ avatar: base64String });
             onUpdate(updated);
             setSuccessMsg('Profile photo updated');
             setTimeout(() => setSuccessMsg(''), 3000);
        } catch (error) {
             console.error("Failed to save image", error);
             setSuccessMsg('Failed to save image');
        }
      };

      reader.readAsDataURL(file);
    }
  };

  if (!user) return <div className="text-slate-900 dark:text-white">Loading profile...</div>;

  return (
    <div className="max-w-4xl mx-auto space-y-6 animate-fade-in pb-24 relative z-10">

        {/* Header Profile Card */}
        <div className="glass-panel p-6 md:p-8 rounded-3xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-r from-primary/30 via-secondary/30 to-accent/30"></div>

            <div className="relative z-10 flex flex-col md:flex-row items-end md:items-center gap-6 mt-12">
                <div className="relative group mx-auto md:mx-0">
                    <div className="w-32 h-32 rounded-3xl bg-slate-100 dark:bg-[#0B0F19] p-1.5 shadow-2xl">
                        <div className="w-full h-full rounded-2xl overflow-hidden bg-slate-200 dark:bg-slate-800 flex items-center justify-center relative">
                            {formData.avatar ? (
                                <img src={formData.avatar} alt="Profile" className="w-full h-full object-cover" />
                            ) : (
                                <UserIcon size={48} className="text-slate-400 dark:text-slate-500" />
                            )}
                            <div 
                                onClick={() => fileInputRef.current?.click()}
                                className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer backdrop-blur-sm"
                            >
                                <Camera className="text-white" />
                            </div>
                        </div>
                    </div>
                    <input 
                        type="file" 
                        ref={fileInputRef} 
                        className="hidden" 
                        accept="image/*" 
                        onChange={handleImageUpload}
                    />
                </div>

                <div className="flex-1 text-center md:text-left">
                    <h1 className="text-3xl font-bold text-slate-900 dark:text-white mb-1">{formData.name || 'User'}</h1>
                    <p className="text-primary font-medium">{formData.title || t.title}</p>
                    <div className="flex items-center justify-center md:justify-start gap-4 mt-4 text-sm text-slate-500 dark:text-slate-400">
                        <span className="flex items-center gap-1.5 bg-black/5 dark:bg-white/5 px-3 py-1 rounded-full border border-black/5 dark:border-white/5 shadow-sm">
                            <Shield size={14} className="text-emerald-600 dark:text-emerald-400" />
                            {user.role === 'admin' ? 'Administrator' : 'Premium Member'}
                        </span>
                        <span className="hidden md:inline text-slate-500 dark:text-slate-400">{t.joined} {new Date(user.created_at).toLocaleDateString()}</span>
                    </div>
                </div>

                <button 
                    onClick={handleSave}
                    disabled={loading}
                    className="w-full md:w-auto flex items-center justify-center gap-2 bg-slate-900 dark:bg-white text-white dark:text-primary px-6 py-3 rounded-xl font-bold shadow-lg shadow-black/10 dark:shadow-white/10 hover:shadow-xl transition-all active:scale-95 disabled:opacity-70 cursor-pointer z-20"
                >
                    {loading ? <div className="w-5 h-5 border-2 border-current border-t-transparent rounded-full animate-spin" /> : <Save size={20} />}
                    <span>{t.save}</span>
                </button>
            </div>

            {successMsg && (
                <div className="absolute top-4 right-4 bg-emerald-500/20 text-emerald-600 dark:text-emerald-300 border border-emerald-500/30 px-4 py-2 rounded-xl flex items-center gap-2 text-sm animate-fade-in z-20 shadow-lg backdrop-blur-md">
                    <CheckCircle size={16} />
                    {successMsg}
                </div>
            )}
        </div>

        {/* Content Tabs */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="md:col-span-1">
                <div className="flex md:flex-col gap-2 overflow-x-auto pb-2 md:pb-0 scrollbar-hide">
                    {[
                        { id: 'general', label: t.tabs.general, icon: UserIcon },
                        { id: 'preferences', label: t.tabs.pref, icon: Monitor },
                        { id: 'data', label: t.tabs.data, icon: Shield },
                    ].map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id as any)}
                            className={`flex-shrink-0 flex items-center gap-3 px-4 py-3 rounded-xl transition-all whitespace-nowrap cursor-pointer ${
                                activeTab === tab.id 
                                ? 'bg-primary/20 text-primary dark:text-white border border-primary/30 shadow-lg shadow-primary/10' 
                                : 'text-slate-500 dark:text-slate-400 hover:bg-black/5 dark:hover:bg-white/5 hover:text-slate-900 dark:hover:text-white bg-black/5 dark:bg-white/5 md:bg-transparent'
                            }`}
                        >
                            <tab.icon size={18} />
                            <span className="font-medium">{tab.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="md:col-span-3 glass-panel p-6 rounded-2xl min-h-[400px]">
                {activeTab === 'general' && (
                    <div className="space-y-6 animate-slide-up">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Display Name</label>
                                <input 
                                    type="text" 
                                    value={formData.name}
                                    onChange={e => setFormData({...formData, name: e.target.value})}
                                    className="w-full glass-input rounded-xl px-4 py-3 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary/50"
                                    placeholder="Your Name"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Job Title</label>
                                <input 
                                    type="text" 
                                    value={formData.title}
                                    onChange={e => setFormData({...formData, title: e.target.value})}
                                    className="w-full glass-input rounded-xl px-4 py-3 text-slate-900 dark:text-white focus:ring-2 focus:ring-primary/50"
                                    placeholder="e.g. Founder"
                                />
                            </div>
                            <div className="space-y-2 md:col-span-2">
                                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Email Address</label>
                                <input 
                                    type="email" 
                                    value={user.email}
                                    disabled
