            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-40 w-72 glass-panel border-r border-slate-200 dark:border-white/5 transform transition-transform duration-300 ease-[cubic-bezier(0.23,1,0.32,1)] lg:translate-x-0 lg:static lg:block 
        bg-white/95 dark:bg-[#0B0F19]/95 backdrop-blur-xl
