      `}>
        <div className="h-full flex flex-col pt-20 lg:pt-0">
          <div className="p-8 pb-4 hidden lg:block">
            <div className="flex flex-col items-center justify-center mb-6 animate-slide-up text-center cursor-pointer" onClick={() => onNavigate('dashboard')}>
              <div className="w-full flex justify-center mb-6 group">
                {/* LARGE SIDEBAR LOGO */}
