                    <VLogo size={120} />
                </div>
              </div>
              <div>
                <h1 className="font-bold text-2xl tracking-tight leading-none text-slate-900 dark:text-white">VContact</h1>
                <p className="text-[10px] text-primary font-bold tracking-[0.2em] mt-1 uppercase opacity-80">Premium System</p>
              </div>
            </div>
            <div className="h-px w-full bg-gradient-to-r from-transparent via-slate-200 dark:via-white/10 to-transparent mb-6" />
          </div>

          <nav className="flex-1 px-4 space-y-2 overflow-y-auto py-4">
            <NavItem id="dashboard" icon={Users} label={t.network} />
            <NavItem id="subscription" icon={CreditCard} label={t.subscription} />
            <NavItem id="faq" icon={HelpCircle} label={t.faq} />
            <NavItem id="profile" icon={UserIcon} label={t.profile} />

            {/* Conditional Admin Link or Lock Button */}
            {user?.role === 'admin' ? (
                 <NavItem id="stats" icon={LayoutDashboard} label={t.admin} adminOnly={true} />
            ) : (
                <button
                    onClick={() => { setIsAdminModalOpen(true); setIsMobileMenuOpen(false); }}
                    className="w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 group relative overflow-hidden cursor-pointer text-slate-500 dark:text-slate-400 hover:text-rose-500 hover:bg-rose-500/10"
                >
                    <Lock size={20} className="group-hover:text-rose-500 transition-colors relative z-10" />
                    <span className="font-medium relative z-10">{t.adminAccess}</span>
                </button>
            )}
          </nav>

          <div className="p-4 pb-8 lg:pb-4">
            <div className={`glass-panel rounded-2xl p-4 mb-4 relative overflow-hidden group transition-colors cursor-pointer border ${user?.plan === 'vip' ? 'border-yellow-500/30 bg-yellow-500/5' : 'border-slate-200 dark:border-white/5 bg-slate-50 dark:bg-white/5'}`}>
                <div className="absolute top-0 right-0 p-2 opacity-20 group-hover:opacity-40 transition-opacity">
                    {user?.plan === 'vip' ? <Crown className="text-yellow-400" size={40} /> : <Zap className="text-emerald-400" size={40} />}
                </div>
                <p className="text-xs text-slate-500 dark:text-slate-400 mb-2">{t.plan}</p>
                <div className="flex justify-between items-end relative z-10">
                    <span className={`text-sm font-bold ${user?.plan === 'vip' ? 'text-yellow-600 dark:text-yellow-400' : 'text-slate-900 dark:text-white'}`}>
                        {user?.plan === 'vip' ? t.vip : t.free}
