            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 relative z-10 h-screen overflow-y-auto pt-20 lg:pt-0 scroll-smooth w-full">
        <div className="max-w-7xl mx-auto p-4 lg:p-8 pb-32 lg:pb-20">
          {children}
