                                        />
                                    </div>
                                    <div className="relative group">
                                        <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-primary transition-colors" size={20} />
                                        <input
                                            type="password"
                                            value={password}
                                            onChange={(e) => setPassword(e.target.value)}
                                            placeholder="Password (Optional for Users)"
                                            className="w-full pl-12 pr-4 py-4 rounded-xl glass-input text-white placeholder-slate-500 focus:ring-2 focus:ring-primary/50 transition-all"
                                            disabled={loading}
                                        />
                                    </div>
                                </div>

                                <button
                                    type="submit"
                                    disabled={loading || isGoogleLoading}
                                    className="w-full bg-gradient-to-r from-primary to-accent hover:from-primary/90 hover:to-accent/90 text-white font-semibold py-4 rounded-xl shadow-lg shadow-primary/25 flex items-center justify-center gap-2 transition-all transform active:scale-95 disabled:opacity-70 group"
                                >
                                    {loading && !isGoogleLoading ? (
                                        <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                    ) : (
                                        <>
                                            <span>{password ? 'Secure Login' : 'Send Magic Link'}</span>
                                            <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
                                        </>
                                    )}
                                </button>
                            </form>
                        </div>
                    </>
                ) : (
                    <div className="text-center py-8 animate-fade-in">
                        <div className="w-16 h-16 bg-emerald-500/20 text-emerald-400 rounded-full flex items-center justify-center mx-auto mb-4 shadow-[0_0_20px_rgba(16,185,129,0.3)]">
                            <CheckCircle2 size={32} />
                        </div>
                        <h3 className="text-xl font-bold text-white mb-2">Check your email</h3>
                        <p className="text-slate-400 mb-6">Magic link sent to <span className="text-white font-medium">{email}</span></p>
                    </div>
                )}
            </div>
        </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
