import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Search, Plus, Download, Filter, FileText, Trash2, Edit2, 
  Briefcase, User, Users, GraduationCap, Video, HelpCircle,
  Camera, X, Crown, Lock, Mail, Phone, RefreshCw, Smartphone, Cloud, MessageCircle, CheckCircle2
} from 'lucide-react';
import { Contact, Category, User as UserType } from '../types';
import { getContacts, addContact, deleteContact, logExport, updateContact, upgradeToVip } from '../services/storage';
import { exportToCSV, exportToPDF } from '../utils/export';
import { translations } from '../utils/translations';

interface DashboardProps {
  user: UserType;
  lang: 'en' | 'fr';
}

export const Dashboard: React.FC<DashboardProps> = ({ user, lang }) => {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<Category | 'All'>('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showUpgradeModal, setShowUpgradeModal] = useState(false);
  const [isSyncModalOpen, setIsSyncModalOpen] = useState(false);
  const [editingContact, setEditingContact] = useState<Contact | null>(null);
  const [upgradeLoading, setUpgradeLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = translations[lang].dashboard;

  // Sync States
  const [syncStatus, setSyncStatus] = useState({
      google: false,
      whatsapp: false,
      phone: false
  });
  const [syncLoading, setSyncLoading] = useState({
      google: false,
      whatsapp: false,
      phone: false
  });

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    category: 'Business' as Category,
    note: '',
    avatar: ''
  });

  useEffect(() => {
    loadContacts();
  }, [user.id]);

  const loadContacts = async () => {
    const data = await getContacts(user.id);
    setContacts(data);
  };

  const handleExport = async (type: 'PDF' | 'EXCEL') => {
    if (user.plan === 'free' && type === 'PDF') {
        alert("PDF Export is a VIP Feature. Please upgrade.");
        setShowUpgradeModal(true);
        return;
    }
    await logExport(type, user.id);
    if (type === 'EXCEL') {
        exportToCSV(contacts);
    } else {
        exportToPDF(contacts, user.email);
    }
  };

  const handleSync = (platform: 'google' | 'whatsapp' | 'phone') => {
      setSyncLoading(prev => ({ ...prev, [platform]: true }));

      // Simulate API call delay
      setTimeout(() => {
          setSyncLoading(prev => ({ ...prev, [platform]: false }));
          setSyncStatus(prev => ({ ...prev, [platform]: true }));

          // Optionally simulate adding a contact
          if (Math.random() > 0.5) {
               addContact({
                   name: platform === 'google' ? 'Google Contact' : platform === 'whatsapp' ? 'WhatsApp Friend' : 'Phone Contact',
                   email: `imported_${platform}@example.com`,
                   phone: '+123456789',
                   category: 'Other',
                   note: `Imported via ${platform}`,
                   user_id: user.id
               }, user.plan).then(() => loadContacts()).catch(() => {});
          }

      }, 2000);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024 * 2) {
        alert("File too large. Please select an image under 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
        if (editingContact) {
            await updateContact(editingContact.id, { ...formData, user_id: user.id });
        } else {
            await addContact({ ...formData, user_id: user.id }, user.plan);
        }
        setIsModalOpen(false);
        resetForm();
        loadContacts();
    } catch (err: any) {
        if (err.message === 'LIMIT_REACHED') {
            setIsModalOpen(false);
            setShowUpgradeModal(true);
        }
    }
  };

  const handleUpgrade = async () => {
      setUpgradeLoading(true);
      await upgradeToVip(user.id);
      window.location.reload(); // Quick way to refresh session state in this demo
  };

  const resetForm = () => {
    setEditingContact(null);
    setFormData({ name: '', email: '', phone: '', category: 'Business', note: '', avatar: '' });
  };

  const handleEdit = (contact: Contact) => {
      setEditingContact(contact);
      setFormData({
          name: contact.name,
          email: contact.email,
          phone: contact.phone,
          category: contact.category,
          note: contact.note,
          avatar: contact.avatar || ''
      });
      setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
      if(confirm('Are you sure you want to remove this connection from your secure vault?')) {
        await deleteContact(id);
        loadContacts();
      }
  };

  const filteredContacts = useMemo(() => {
    return contacts.filter(c => {
      const matchesSearch = c.name.toLowerCase().includes(search.toLowerCase()) || 
                            c.email.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = filterCategory === 'All' || c.category === filterCategory;
      return matchesSearch && matchesCategory;
    });
  }, [contacts, search, filterCategory]);

  const CategoryIcon = ({ category }: { category: Category }) => {
      switch(category) {
          case 'Business': return <Briefcase size={14} className="text-blue-400" />;
          case 'Family': return <Users size={14} className="text-green-400" />;
          case 'Student': return <GraduationCap size={14} className="text-yellow-400" />;
          case 'Creator': return <Video size={14} className="text-purple-400" />;
          case 'Friends': return <User size={14} className="text-pink-400" />;
          default: return <HelpCircle size={14} className="text-slate-400" />;
      }
  };

  return (
    <div className="space-y-6 animate-slide-up relative">

      {/* Banner for Free Users */}
      {user.plan === 'free' && (
          <div className="bg-gradient-to-r from-indigo-900 to-purple-900 border border-white/10 rounded-2xl p-4 flex items-center justify-between shadow-xl">
              <div className="flex items-center gap-3">
                  <div className="p-2 bg-white/10 rounded-lg"><Crown className="text-yellow-400" size={24} /></div>
                  <div>
                      <h4 className="font-bold text-white">{t.unlock}</h4>
                      <p className="text-xs text-slate-300">{t.unlockDesc}</p>
                  </div>
              </div>
              <button 
                onClick={() => setShowUpgradeModal(true)}
                className="bg-white text-indigo-900 px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-100 transition-colors"
              >
                  {t.upgrade}
              </button>
          </div>
      )}

      {/* Header Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group hover:bg-white/5 transition-colors">
            <div className="absolute right-0 top-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity transform group-hover:scale-110 duration-500">
                <Users size={60} className="text-slate-900 dark:text-white" />
            </div>
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-1">{t.totalNetwork}</p>
            <h3 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight">{contacts.length} {user.plan==='free' && <span className="text-lg text-slate-400 font-normal">/ 5</span>}</h3>
            <p className="text-xs text-emerald-600 dark:text-emerald-400 mt-2 flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                {t.stored}
            </p>
        </div>
        <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group hover:bg-white/5 transition-colors">
            <div className="absolute right-0 top-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity transform group-hover:scale-110 duration-500">
                <Briefcase size={60} className="text-slate-900 dark:text-white" />
            </div>
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-1">{t.business}</p>
            <h3 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight">{contacts.filter(c => c.category === 'Business').length}</h3>
            <p className="text-xs text-primary mt-2">{t.targets}</p>
        </div>
        <div className="glass-panel p-6 bg-gradient-to-br from-primary/10 to-purple-900/10 dark:from-primary/20 dark:to-purple-900/20 rounded-2xl relative overflow-hidden border-primary/20 hover:border-primary/40 transition-colors">
             <div className="flex flex-col h-full justify-between">
                <div>
                    <h3 className="text-slate-900 dark:text-white font-bold text-lg">{t.growth}</h3>
