export type UserRole = 'user' | 'admin';
export type PlanType = 'free' | 'vip';

export interface GeoLocation {
  city: string;
  country: string;
  lat: number;
  lng: number;
  ip: string;
}

export interface User {
  id: string;
  email: string;
  name?: string;
  avatar?: string;
  title?: string;
  role: UserRole;
  plan: PlanType; // New field for VIP
  location?: GeoLocation; // New field for Admin tracking
  lastActive?: string;
  created_at: string;
  preferences?: {
    theme?: 'dark' | 'light' | 'system';
    notifications?: boolean;
    publicProfile?: boolean;
    language?: 'en' | 'fr';
  };
}

export type Category = 'Business' | 'Family' | 'Friends' | 'Student' | 'Creator' | 'Other';

export interface Contact {
  id: string;
  user_id: string;
  name: string;
  phone: string;
