import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Search, Plus, Download, Filter, FileText, Trash2, Edit2, 
  Briefcase, User, Users, GraduationCap, Video, HelpCircle,
  Camera, X, Crown, Lock, Mail, Phone, RefreshCw, Smartphone, Cloud, MessageCircle, CheckCircle2, Share2, Upload
} from 'lucide-react';
import { Contact, Category, User as UserType } from '../types';
import { getContacts, addContact, deleteContact, logExport, updateContact, upgradeToVip } from '../services/storage';
import { exportToCSV, exportToPDF } from '../utils/export';
import { translations } from '../utils/translations';

interface DashboardProps {
  user: UserType;
  lang: 'en' | 'fr';
}

export const Dashboard: React.FC<DashboardProps> = ({ user, lang }) => {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<Category | 'All'>('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showUpgradeModal, setShowUpgradeModal] = useState(false);
  const [isSyncModalOpen, setIsSyncModalOpen] = useState(false);
  const [editingContact, setEditingContact] = useState<Contact | null>(null);
  const [upgradeLoading, setUpgradeLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);
  const t = translations[lang].dashboard;

  // Sync States
  const [importStatus, setImportStatus] = useState<string | null>(null);
  const [importLoading, setImportLoading] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    category: 'Business' as Category,
    note: '',
    avatar: ''
  });

  useEffect(() => {
    loadContacts();
  }, [user.id]);

  const loadContacts = async () => {
    const data = await getContacts(user.id);
    setContacts(data);
  };

  const handleExport = async (type: 'PDF' | 'EXCEL') => {
    if (user.plan === 'free' && type === 'PDF') {
        alert("PDF Export is a VIP Feature. Please upgrade.");
        setShowUpgradeModal(true);
        return;
    }
    await logExport(type, user.id);
    if (type === 'EXCEL') {
        exportToCSV(contacts);
    } else {
        exportToPDF(contacts, user.email);
    }
  };

  const parseAndImportFile = (file: File) => {
      setImportLoading(true);
      const reader = new FileReader();

      reader.onload = async (e) => {
          const text = e.target?.result as string;
          let newCount = 0;

          try {
              if (file.name.endsWith('.csv')) {
                  const lines = text.split('\n');
                  for (let i = 1; i < lines.length; i++) { // Skip header
                      const line = lines[i].trim();
                      if (!line) continue;
                      // Simple split by comma, handling generic CSV
                      const cols = line.split(',');
                      if (cols.length >= 2) {
                          // Try to guess columns: Name, Phone, Email
                          const name = cols[0]?.replace(/"/g, '') || 'Imported Contact';
                          const phone = cols[1]?.replace(/"/g, '') || '';
                          const email = cols[2]?.replace(/"/g, '') || '';

                          await addContact({
                              name, phone, email, category: 'Other', note: 'Imported via CSV', user_id: user.id
                          }, user.plan);
                          newCount++;
                      }
                  }
              } else if (file.name.endsWith('.vcf')) {
                  // Basic VCF parse
                  const vcards = text.split('BEGIN:VCARD');
                  for (const vcard of vcards) {
                      if (!vcard.trim()) continue;
                      const fnMatch = vcard.match(/FN:(.*)/);
                      const telMatch = vcard.match(/TEL.*:(.*)/);
                      const emailMatch = vcard.match(/EMAIL.*:(.*)/);

                      const name = fnMatch ? fnMatch[1].trim() : '';
                      if (name) {
                           await addContact({
                              name, 
                              phone: telMatch ? telMatch[1].trim() : '', 
                              email: emailMatch ? emailMatch[1].trim() : '', 
                              category: 'Other', 
                              note: 'Imported via vCard', 
                              user_id: user.id
                          }, user.plan);
                          newCount++;
                      }
                  }
              }
              setImportStatus(`${newCount} contacts imported successfully.`);
              loadContacts();
          } catch (err: any) {
              setImportStatus('Error importing: ' + err.message);
          } finally {
              setImportLoading(false);
          }
      };

      reader.readAsText(file);
  };

  const handleImportClick = () => {
      importInputRef.current?.click();
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024 * 2) {
        alert("File too large. Please select an image under 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
        if (editingContact) {
            await updateContact(editingContact.id, { ...formData, user_id: user.id });
        } else {
            await addContact({ ...formData, user_id: user.id }, user.plan);
        }
        setIsModalOpen(false);
        resetForm();
        loadContacts();
    } catch (err: any) {
        if (err.message === 'LIMIT_REACHED') {
            setIsModalOpen(false);
            setShowUpgradeModal(true);
        }
    }
  };

  const handleUpgrade = async () => {
      setUpgradeLoading(true);
      await upgradeToVip(user.id);
      window.location.reload(); // Quick way to refresh session state in this demo
  };

  const resetForm = () => {
    setEditingContact(null);
    setFormData({ name: '', email: '', phone: '', category: 'Business', note: '', avatar: '' });
  };

  const handleEdit = (contact: Contact) => {
      setEditingContact(contact);
      setFormData({
          name: contact.name,
          email: contact.email,
          phone: contact.phone,
          category: contact.category,
          note: contact.note,
          avatar: contact.avatar || ''
      });
      setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
      if(confirm(t.deleteConfirm)) {
        await deleteContact(id);
        loadContacts();
      }
  };

  const handleShare = (contact: Contact) => {
      if (navigator.share) {
          navigator.share({
              title: contact.name,
              text: `Contact Info for ${contact.name}\nPhone: ${contact.phone}\nEmail: ${contact.email}`,
          }).then(() => {
              alert(t.shareSuccess);
          }).catch(() => {});
      } else {
          // Fallback
          const text = `${contact.name}\n${contact.phone}\n${contact.email}`;
          navigator.clipboard.writeText(text);
          alert(t.shareSuccess + " (Copied to Clipboard)");
      }
  };

  const filteredContacts = useMemo(() => {
    return contacts.filter(c => {
      const matchesSearch = c.name.toLowerCase().includes(search.toLowerCase()) || 
                            c.email.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = filterCategory === 'All' || c.category === filterCategory;
      return matchesSearch && matchesCategory;
    });
  }, [contacts, search, filterCategory]);

  const CategoryIcon = ({ category }: { category: Category }) => {
