import React, { useState, useEffect, useRef } from 'react';
import { User, Message } from '../types';
import { getAllUsers, getMessages, sendMessage } from '../services/storage';
import { translations } from '../utils/translations';
import { Send, Search, Circle, MessageSquare } from 'lucide-react';

interface MessagesProps {
    user: User;
    lang: 'en' | 'fr';
}

export const Messages: React.FC<MessagesProps> = ({ user, lang }) => {
    const t = translations[lang].messages;
    const [users, setUsers] = useState<User[]>([]);
    const [activeChat, setActiveChat] = useState<User | null>(null);
    const [messages, setMessages] = useState<Message[]>([]);
    const [inputText, setInputText] = useState('');
    const [search, setSearch] = useState('');
    const scrollRef = useRef<HTMLDivElement>(null);

    // Load available users to chat with (excluding self)
    useEffect(() => {
        getAllUsers().then(all => {
            setUsers(all.filter(u => u.id !== user.id));
        });
    }, [user.id]);

    // Load messages when active chat changes
    useEffect(() => {
        const load = async () => {
            const allMsgs = await getMessages(user.id);
            setMessages(allMsgs);
            if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        };
        load();

        // Simple polling for new messages (demo purposes)
        const interval = setInterval(load, 2000);
        return () => clearInterval(interval);
    }, [user.id, activeChat]);

    const handleSend = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activeChat || !inputText.trim()) return;

        await sendMessage({
            senderId: user.id,
            receiverId: activeChat.id,
            content: inputText,
        });

        // Mock reply
        setTimeout(async () => {
             await sendMessage({
                senderId: activeChat.id,
                receiverId: user.id,
                content: lang === 'en' ? "Thanks for your message! I'll get back to you shortly." : "Merci pour votre message ! Je reviens vers vous rapidement.",
            });
        }, 1500);

        setInputText('');
    };

    const getConversation = (partnerId: string) => {
        return messages
            .filter(m => (m.senderId === user.id && m.receiverId === partnerId) || (m.senderId === partnerId && m.receiverId === user.id))
            .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
    };

    const filteredUsers = users.filter(u => 
        (u.name || u.email).toLowerCase().includes(search.toLowerCase())
    );

    return (
        <div className="h-[calc(100vh-140px)] flex gap-4 animate-fade-in">
            {/* Sidebar List */}
            <div className="w-full md:w-80 glass-panel rounded-2xl flex flex-col overflow-hidden">
